:root {
  --bg: #201f1d; --panel: #191816; --line: #302f2c; --text: #e8eaec; --dim: #8a9099; --faint: #64625e;
  --tile: #201f1d; --ink: #a3a8b0; --ink-dim: #73706b; --accent: #22e6ff; --play: #4fd18b;
  --cell: 40px; --gap: 8px; --rowbtn: calc(var(--cell) * 3 + var(--gap) * 2);
  --tile-size: 92px; --tile-gap: 6px; --tile-r: 12px;
  --tile-texture: none;   /* TODO(design): tile artwork */
  --key-texture: none;    /* TODO(design): key artwork */
  --knob-texture: none;   /* TODO(design): knob artwork */
  color-scheme: dark;
}
* { box-sizing: border-box; }
[hidden] { display: none !important; }
html, body { height: 100%; margin: 0; }
body { background: var(--bg); color: var(--text); font: 13px/1.35 -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif; display: grid; grid-template-rows: auto 1fr auto; grid-template-columns: minmax(0, 1fr); overflow: hidden; } /* never wider than the window: the header wraps instead */
button, select, input { font: inherit; color: var(--text); background: #292826; border: 1px solid #383734; border-radius: 6px; padding: 4px 9px; cursor: pointer; }
button:hover { border-color: var(--dim); }
button:disabled { opacity: .45; cursor: default; }
input[type=number] { width: 60px; font-variant-numeric: tabular-nums; }
.field { display: inline-flex; align-items: center; gap: 6px; color: var(--dim); white-space: nowrap; }
.field output { color: var(--text); font-variant-numeric: tabular-nums; }

header { display: flex; align-items: center; gap: 8px 10px; padding: 9px 16px; background: var(--panel); border-bottom: 1px solid var(--line); flex-wrap: wrap; min-width: 0; }
header > * { flex-shrink: 0; } header > #status { flex-shrink: 1; }
.brand { font-size: 17px; margin-right: 6px; } .brand b { color: var(--accent); }
#play.on { background: var(--play); color: #171615; border-color: var(--play); }
#clock { font-variant-numeric: tabular-nums; min-width: 72px; color: var(--dim); }
.spacer { flex: 1; }
#busy { width: 9px; height: 9px; border-radius: 50%; background: #383734; } #busy.on { background: var(--accent); box-shadow: 0 0 8px var(--accent); }
#status { color: var(--dim); flex: 0 1 300px; min-width: 60px; max-width: 380px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; } #status.err { color: #ff7a7a; }
header .groove { display: flex; align-items: center; gap: 6px; padding-left: 8px; border-left: 1px solid var(--line); }
#gen { font-weight: 700; color: #160016; background: linear-gradient(135deg, #ff5fd2, #b300b6 55%, #7a35ff); border: 0; padding: 5px 14px; border-radius: 8px; box-shadow: 0 0 14px rgba(179,0,182,.45); }
#gen:hover { filter: brightness(1.12); }
#genpop { position: fixed; z-index: 40; width: 460px; padding: 14px; border-radius: 16px; background: rgba(26, 25, 23, .98); box-shadow: 0 0 0 1px #302f2c, 0 22px 60px rgba(0,0,0,.6); display: grid; gap: 12px; }
#genpop .gp-h { margin: 0; font-weight: 700; font-size: 14px; } #genpop .gp-h span { display: block; font-weight: 400; font-size: 11px; color: var(--dim); margin-top: 2px; }
#genpop .gp-styles { display: grid; grid-template-columns: 1fr 1fr; gap: 2px 10px; padding: 4px; border-radius: 11px; background: #161514; box-shadow: inset 0 0 0 1px #2e2d2a; }
#genpop .gp-styles button { all: unset; cursor: pointer; display: grid; grid-template-columns: 1fr auto; gap: 0 8px; padding: 6px 9px; border-radius: 8px; min-width: 0; }
#genpop .gp-styles button:hover { background: #22211f; }
#genpop .gp-styles button.on { background: #22211f; box-shadow: inset 0 0 0 1px var(--accent); }
#genpop .gp-styles b { font-size: 12.5px; } #genpop .gp-styles .bpm { font-size: 10.5px; color: #77746f; font-variant-numeric: tabular-nums; align-self: center; }
#genpop .gp-styles .bpm.near { color: #9be7b0; }
#genpop .gp-styles .ds { grid-column: 1 / -1; font-size: 10.5px; color: var(--dim); line-height: 1.3; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
/* Generate is one of the shop's keys (tester, 2026-11-04: "not the pink buttons"); only its size is set here. */
#genpop .gp-go.capbtn { width: 100%; height: 40px; font-size: 13px; }
#genpop .gp-go b { font-weight: 700; } #genpop .gp-go #gogen-style { opacity: .85; font-weight: 500; }
#genpop.working .gp-go { filter: grayscale(.6) brightness(.8); pointer-events: none; }
#genpop.working .gp-go .gp-go-i { display: inline-block; animation: fk-spin 800ms linear infinite; }
#genpop.working .gp-styles { opacity: .55; pointer-events: none; }
#genpop .gp-row { display: flex; flex-wrap: wrap; justify-content: space-between; align-items: center; gap: 8px 12px; } #genpop input[type=range] { width: 110px; accent-color: var(--accent); }
#genpop .gp-src { display: grid; grid-template-columns: repeat(3, 1fr); gap: 4px; padding: 3px; border-radius: 11px; background: #161514; box-shadow: inset 0 0 0 1px #2e2d2a; }
#genpop .gp-src button { all: unset; cursor: pointer; display: grid; gap: 2px; padding: 7px 9px; border-radius: 8px; }
#genpop .gp-src button:hover { background: #22211f; }
#genpop .gp-src button.on { background: #292826; box-shadow: inset 0 0 0 1px var(--accent); }
#genpop .gp-src button:disabled { opacity: .4; cursor: default; }
#genpop .gp-src b { font-size: 12px; } #genpop .gp-src span { font-size: 10.5px; color: var(--dim); line-height: 1.3; }
#genpop select { font-size: 12px; }
#genpop.working .gp-src { opacity: .55; pointer-events: none; cursor: progress; }
#genpop .gp-t { margin: 0; font-size: 11px; color: var(--faint); }
header .groove input[type=number] { width: 54px; }
.rowbtn { position: relative; overflow: hidden; }
.rowbtn.uploading::after { content: ''; position: absolute; left: 0; bottom: 0; height: 2px; width: var(--up, 0%); background: var(--tc); transition: width 120ms; }
.key.pending { cursor: progress; }
.rowbtn.locked .nm::after { content: ' 🔒'; font-size: 9px; }
#close { background: none; border: 0; color: var(--dim); font-size: 15px; padding: 2px 6px; margin-left: 2px; } #close:hover { color: var(--text); background: #2d2c2a; }
#setup { background: var(--accent); color: #11100f; border-color: var(--accent); font-weight: 600; }
.stat output { font-size: 12px; color: var(--dim); }

main { overflow: auto; padding: 22px 16px; display: grid; justify-content: center; align-content: start; grid-auto-rows: max-content; gap: 14px; }
#grid { display: grid; gap: var(--gap); padding: 18px; background: var(--panel); border-radius: 14px; user-select: none; width: max-content; max-width: 100%; }
.below { display: flex; align-items: center; gap: 14px; }
.hint { color: var(--faint); font-size: 12px; margin: 0; }
.steps-head { display: flex; gap: var(--gap); margin-left: calc(var(--rowbtn) + var(--gap)); color: var(--faint); font-size: 10px; }
.steps-head span { width: var(--cell); text-align: center; flex: none; } .steps-head span.ph { color: var(--play); }
/* Each row's lane (lanes.ts) sits right above its keys, on the same columns. */
.track { display: grid; gap: 3px; }
.lane { position: relative; margin-left: calc(var(--rowbtn) + var(--gap)); }
.lane canvas { display: block; border-radius: 5px; cursor: pointer; }
.track.selected .lane canvas { box-shadow: 0 0 0 1px color-mix(in srgb, var(--tc) 30%, #302f2c); }
/* Focus panel: under the focused row (main.ts renderFocus). */
/* The focus dock: fixed above the grid (sticky in the scrolling page), as wide as the grid. */
#dock { position: sticky; isolation: isolate; top: 0; z-index: 5; box-sizing: border-box; padding: 10px; border-radius: 12px; background: #1a1917;
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--tc, #454441) 25%, #2e2d2a), 0 10px 24px rgba(0,0,0,.45); min-height: 190px; }
.dock-empty { margin: 0; padding: 4px 2px; max-width: 70ch; }
.focus { display: grid; gap: 8px; min-width: 0; } .focus > * { min-width: 0; }
.ftitle { display: flex; align-items: center; gap: 10px; font-size: 12px; height: 20px; } .ftitle b { color: var(--tc); font-weight: 600; } .ftitle span { color: var(--ink-dim); font-size: 11px; }
.fstrip { min-width: 0; } .fstrip canvas { display: block; border-radius: 6px; cursor: pointer; }
.fhint { margin: 0; font-size: 11px; color: var(--ink-dim); }
/* Focus controls: no boxes. Line faders and text options; colour only on what is set. */
.fx { display: grid; grid-template-columns: repeat(6, minmax(0, 1fr)); gap: 14px 22px; align-items: start; padding: 4px 2px 2px; }
.fx .wide { grid-column: span 2; }
.lb { display: block; font: 600 9px/1 -apple-system, sans-serif; letter-spacing: .09em; text-transform: uppercase; color: #73706b; margin-bottom: 7px; }
.ln { position: relative; cursor: ns-resize; outline: none; padding-bottom: 6px; touch-action: none; user-select: none; }
.ln .v { display: block; font: 500 13px/1 -apple-system, sans-serif; color: #e4e6e9; font-variant-numeric: tabular-nums; margin-bottom: 9px; }
.ln .line { position: relative; display: block; height: 1px; background: #383734; }
.ln .fill { position: absolute; top: -0.5px; height: 2px; background: var(--tc); }
.ln .knob { position: absolute; top: -4px; width: 1px; height: 9px; margin-left: -0.5px; background: #eceef1; }
.ln:hover .line, .ln:focus-visible .line { background: #4f4e4a; }
.ln:focus-visible .lb { color: var(--tc); }
body.fading, body.fading * { cursor: ns-resize !important; }
.os { display: flex; flex-wrap: wrap; gap: 4px 12px; }
.os button { all: unset; cursor: pointer; font: 500 12px/1.6 -apple-system, sans-serif; color: #7d838c; padding-bottom: 1px; }
.os button:hover { color: #c4c8ce; }
.os button.on { color: #eceef1; box-shadow: inset 0 -1.5px 0 var(--tc); }
.os button:focus-visible { outline: 1px solid var(--tc); outline-offset: 2px; }
.os .more { color: #73706b; font-size: 11px; } .os .more:hover { color: #eceef1; }
.focus.lfo-off .lfo { opacity: .35; }
/* Trigger view (zoomview.ts) and knob groups (knobs.ts), after the tester's mockup. */
.fzoom { min-width: 0; } .fzoom canvas { display: block; border-radius: 6px; }
.kgroups { display: flex; gap: 6px; align-items: stretch; height: 88px; } /* the same in step and track mode: the grid never jumps */
.kg { position: relative; display: flex; align-items: flex-start; gap: 2px; padding: 10px 6px 8px; min-width: 0; border-radius: 8px; background: #0d0d0c; }
.kg:first-child { flex: 0 0 auto; justify-content: flex-start; gap: 4px; } /* packed: the spare width goes to Effects */
.kgl { align-self: center; font: 500 11px -apple-system, sans-serif; color: #c4c8ce; margin: 0 6px 0 2px; }
.kn2 { display: grid; justify-items: center; gap: 1px; width: 46px; cursor: ns-resize; outline: none; user-select: none; touch-action: none; }
.kn2 svg { width: 40px; height: 40px; overflow: visible; }
.kn2 .trk { fill: none; stroke: #2e2d2a; stroke-width: 2.5; stroke-linecap: round; }
.kn2 .val { fill: none; stroke: var(--tc); stroke-width: 2.5; stroke-linecap: round; }
.kn2 .dial { fill: #d6d8db; transition: fill 120ms; }
.kn2 .ind { stroke: #1d1c1a; stroke-width: 2.4; stroke-linecap: round; }
.kn2:hover .dial, .kn2:focus-visible .dial { fill: #eceef1; }
.kn2 .kl { font: 500 11px/1.2 -apple-system, sans-serif; color: #c4c8ce; margin-top: 3px; white-space: nowrap; }
.kn2 .kv { font: 500 10px/1.2 -apple-system, sans-serif; color: #7d838c; font-variant-numeric: tabular-nums; white-space: nowrap; }
.kn2.off .dial { fill: #726f6a; } .kn2.off .val { stroke: #3e3d3a; } .kn2.off .kl { color: #7d838c; }
.kn2 .val { transition: opacity 160ms; } .kn2.spinning .val { opacity: 0; }
.kn2.empty { cursor: default; } .kn2.empty .dial { fill: #3e3d3a; } .kn2.empty .ind { stroke: #726f6a; } .kn2.empty .kl { color: #73706b; }
.focus.empty .eqcurve { pointer-events: none; }
.focus .ftitle b:empty::before { content: ''; }
.eqcurve { all: unset; cursor: pointer; align-self: center; width: 84px; height: 40px; border-radius: 6px; padding: 2px 4px; }
.eqcurve:hover { background: #191817; box-shadow: inset 0 0 0 1px #302f2c; } .eqcurve canvas { display: block; width: 100%; height: 100%; }
.fxslot { align-items: center; padding-right: 10px; }
.addfx { width: 34px; height: 34px; border-radius: 50%; border: 0; background: #726f6a; color: #eceef1; font-size: 16px; padding: 0; }
.addfx:hover { background: var(--tc); color: #111; }
.fxslot { flex: 1 1 auto; gap: 6px; } .fxlist { display: flex; flex-wrap: wrap; gap: 4px; align-items: center; min-width: 0; flex: 1; max-height: 64px; overflow: auto; }
.fxnote { font-size: 11px; color: #73706b; }
.fxchip { display: inline-flex; align-items: center; gap: 4px; padding: 2px 4px 2px 2px; border-radius: 12px; background: #201f1d; box-shadow: inset 0 0 0 1px #302f2c; font-size: 11px; max-width: 150px; }
.fxchip b { font-weight: 500; color: #d4d7dc; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.fxchip button { all: unset; cursor: pointer; width: 16px; text-align: center; color: #73706b; font-size: 10px; } .fxchip button:hover { color: #eceef1; }
.fxchip button[data-fxin] { color: var(--tc); } .fxchip.byp button[data-fxin] { color: #565451; } .fxchip.byp b { color: #7d838c; text-decoration: line-through; }
.fxpop { position: absolute; z-index: 25; width: 320px; max-height: 360px; display: grid; grid-template-rows: auto auto 1fr; gap: 8px; padding: 10px; border-radius: 10px; background: #1d1c1a; box-shadow: 0 0 0 1px #302f2c, 0 14px 36px rgba(0,0,0,.55); }
.fxpop input { width: 100%; }
.fxcats { gap: 2px 10px; }
.fxres { overflow: auto; display: grid; align-content: start; }
.fxres button { all: unset; cursor: pointer; display: flex; justify-content: space-between; gap: 8px; padding: 5px 6px; border-radius: 6px; font-size: 12px; }
.fxres button:hover { background: #292826; } .fxres button b { font-weight: 500; color: #e4e6e9; } .fxres button span { color: #7d838c; font-size: 11px; white-space: nowrap; }
/* Track panel (click a track name): the same panel, with the track's own groups. */
.focus.trackmode .kstep, .focus:not(.trackmode) .ktrack { display: none; }
.tbtns { display: grid; gap: 4px; align-content: center; margin-left: 4px; } .tbtns.two { grid-template-columns: 1fr 1fr; }
.tbtns { gap: 3px; } .tbtns button { font: 500 10.5px/1.2 -apple-system, sans-serif; padding: 2px 7px; color: #c4c8ce; background: #191817; border: 1px solid #302f2c; border-radius: 6px; white-space: nowrap; }
.tbtns button:hover:not(:disabled) { color: #eceef1; border-color: #3e3d3a; }
.tbtns button.on { color: #111; background: var(--tc); border-color: var(--tc); }
button.armed { color: #ff8a8a !important; border-color: #c25454 !important; background: #22211f !important; }
.trackfx { font: 500 10px -apple-system, sans-serif; padding: 3px 7px; color: #7d838c; background: #191817; border: 1px solid #302f2c; border-radius: 10px; white-space: nowrap; align-self: center; }
.trackfx.on { color: #eceef1; border-color: color-mix(in srgb, var(--tc) 55%, #302f2c); }
.ftitle .tname { font: 600 12px -apple-system, sans-serif; color: var(--tc); background: transparent; border: 1px solid transparent; border-radius: 5px; padding: 1px 5px; width: 150px; }
.ftitle .tname:hover { border-color: #302f2c; } .ftitle .tname:focus { outline: none; border-color: color-mix(in srgb, var(--tc) 50%, #302f2c); background: #201f1d; }
.fzoom canvas.strip { cursor: pointer; }

/* EQ window */
#eqwin { position: fixed; inset: 0; z-index: 30; display: grid; place-items: center; background: rgba(0,0,0,.45); }
#eqwin .eqw { width: min(860px, calc(calc(100 * var(--vw, 1vw)) - 32px)); padding: 12px 14px; border-radius: 12px; background: #191817; box-shadow: 0 0 0 1px #302f2c, 0 24px 60px rgba(0,0,0,.6); display: grid; gap: 10px; --ink: #a3a8b0; --ink-dim: #73706b; }
#eqwin header { display: flex; align-items: center; gap: 10px; } #eqwin header b { color: var(--tc); } #eqwin header span { color: #7d838c; font-size: 12px; } #eqwin .sp { flex: 1; }
#eqwin .eqhost { height: 280px; } #eqwin .note { margin: 0; font-size: 11px; color: #73706b; }
#eqwin .eqx-close { font-size: 12px; padding: 4px 12px; }
/* Crosshair: the focused row and column. */
#grid { position: relative; }
/* .track.selected: no row highlight (tester); the selected key keeps its outline */
.colhi { display: none; } /* no column highlight (tester); the step number above still lights */
/* .steps-head span.colsel: no column highlight (tester) */
.key.sel { outline: 2px solid #b300b6; outline-offset: 2px; border-radius: 9px; } /* selection colour: used for nothing else */
/* Key face: the slice of sound under the key (main.ts renderKeyWaves). Tail keys = the sound ringing on. */
/* Waveforms on the keys: hidden for now (the tester has plans for them elsewhere); main.ts still draws them. */
.key canvas.kw { position: absolute; inset: 0; width: 100%; height: 100%; z-index: 1; pointer-events: none; display: none; }
.key.on canvas.kw { display: block; } /* the chop's waveform, on lit keys only */
.key .grip { display: none; position: absolute; z-index: 2; right: -2px; top: 22%; bottom: 22%; width: 6px; border-radius: 3px; background: var(--tc); opacity: 0; cursor: ew-resize; transition: opacity 100ms; }
.key.on:hover .grip, .key.on.sel .grip { opacity: .85; }
.key.held .grip { opacity: .6; }
body.stretching, body.stretching * { cursor: ew-resize !important; }
.lanes { display: grid; gap: 3px; margin-bottom: 6px; }
.lane-name { display: none; }
#grid.combined .lane-name { display: block; position: absolute; right: calc(100% + var(--gap)); top: 0; bottom: 0; width: var(--rowbtn); font: 500 10px/22px -apple-system, sans-serif; color: color-mix(in srgb, var(--tc) 55%, #8a8f96); text-align: right; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
#grid.combined .lane.selected .lane-name { color: var(--tc); }
#grid.combined .lane.selected canvas { box-shadow: 0 0 0 1px color-mix(in srgb, var(--tc) 30%, #302f2c); }
.hseg { display: inline-flex; } .hseg button { padding: 5px 9px; }
.lane-ph { position: absolute; top: -2px; bottom: -2px; width: 2px; margin-left: -1px; background: var(--play); border-radius: 1px; box-shadow: 0 0 6px var(--play); }
.row { display: flex; gap: var(--gap); align-items: center; }

/* Row button: three keys wide, the sample's name in the track colour, plus a 3x3 map of row settings. */
.rowbtn { width: var(--rowbtn); height: var(--cell); flex: none; border-radius: 8px; border: 0; padding: 3px 7px 3px 9px; display: grid; grid-template-rows: 1fr auto; align-content: center; gap: 2px; text-align: left; cursor: pointer;
  background: var(--key-texture), #1d1c1a; color: color-mix(in srgb, var(--tc) 70%, #c9ccd1); box-shadow: inset 0 0 0 1px #32312e; }
.rowbtn:hover, .rowbtn.open { background-color: #252422; box-shadow: inset 0 0 0 1px #3e3d3a; }
.rowbtn .nm { min-width: 0; align-self: end; font: 600 11px/1.15 -apple-system, sans-serif; overflow: hidden; white-space: nowrap; }
/* Mini track controls: mute, solo, duplicate; volume and pan at a glance. */
.rowbtn .rc { display: flex; align-items: center; gap: 3px; min-width: 0; }
.rowbtn .rc button { all: unset; cursor: pointer; width: 15px; height: 13px; display: grid; place-items: center; border-radius: 3px; font: 700 8.5px/1 -apple-system, sans-serif; color: #7d838c; background: #292826; }
.rowbtn .rc button:hover:not(:disabled) { color: #eceef1; background: #353431; }
.rowbtn .rc button.on[data-ract="mute"] { color: #111; background: #e6c35c; } .rowbtn .rc button.on[data-ract="solo"] { color: #111; background: #4fd18b; }
.rowbtn .rc button:disabled { opacity: .3; cursor: default; }
.rowbtn .mvol { position: relative; flex: 1; min-width: 14px; height: 3px; margin-left: 3px; border-radius: 2px; background: #302f2c; overflow: hidden; }
.rowbtn .mvol i { position: absolute; left: 0; top: 0; bottom: 0; background: var(--tc); opacity: .75; }
.rowbtn .mpan { position: relative; width: 16px; height: 3px; border-radius: 2px; background: #302f2c; flex: none; }
.rowbtn .mpan::before { content: ''; position: absolute; left: 50%; top: -1px; bottom: -1px; width: 1px; background: #4f4e4a; }
.rowbtn .mpan i { position: absolute; top: -2px; width: 3px; height: 7px; margin-left: -1.5px; border-radius: 1px; background: var(--tc); }
.rowbtn.empty .nm { opacity: .6; font-style: italic; }
.rowbtn.muted .nm { text-decoration: line-through; opacity: .6; }

/* Nine indicator dots (same 3x3 layout as the menus). */
.map { display: grid; grid-template-columns: repeat(3, 5px); gap: 3px; flex: none; }
.map i { width: 5px; height: 5px; border-radius: 50%; background: currentColor; opacity: .18; } .map i.lit { opacity: 1; }

/* Keys: the designer's key art exactly as rendered (art/key2-*-src.png), the same on every track for
   now (tester's call). keyart.ts can recolour it per track if that comes back. */
.track { --art-off: url(img/key-off.png?v=mwpj9o89); --art-on: url(img/key-on.png?v=mwpj9o89); }
.key { width: var(--cell); height: var(--cell); flex: none; position: relative; cursor: pointer; border: 0; padding: 0; display: grid; place-items: center;
  background: var(--art-off) center / contain no-repeat; transition: transform 60ms, filter 80ms; color: var(--tc); }
.key.on { background-image: var(--art-on); filter: drop-shadow(0 0 5px rgba(80, 230, 245, .45)); } /* the lit key glows */
.key .map { position: relative; z-index: 1; }
/* .key.beat: no filter (keep the art as rendered) */
.key:hover:not(.nosample) { filter: brightness(1.25); }
.key.on:hover:not(.nosample) { filter: brightness(1.1) drop-shadow(0 0 6px rgba(80, 230, 245, .55)); }
/* Its audio isn't in LUNA yet (uploading, or LUNA isn't attached): the art stays as drawn, an amber dot says so. */
.key.pending::after { content: ''; position: absolute; z-index: 3; right: 5px; top: 5px; width: 5px; height: 5px; border-radius: 50%; background: #ffb547; box-shadow: 0 0 6px #ffb547; }
.key.ph { } /* no nudge: the keys stay put under the playhead (it only lights them) */
.key:not(.on).ph { filter: brightness(1.6); }
.key.on.ph { filter: brightness(1.25) drop-shadow(0 0 7px rgba(80, 230, 245, .6)); }
.key.open { outline: 1.5px solid var(--tc); outline-offset: 2px; }
.key.nosample { opacity: .35; } .key.nosample:hover { opacity: .55; }
.row.muted .key.on { filter: saturate(.35) brightness(.75); }
.key:focus-visible, .rowbtn:focus-visible { outline: 2px solid var(--tc); outline-offset: 2px; }

/* ---- Tile menu ---- */
#menu { position: fixed; z-index: 10; left: 0; top: 0; display: grid; grid-template-columns: repeat(3, var(--tile-size)); grid-template-rows: repeat(3, var(--tile-size)); gap: var(--tile-gap);
  padding: 10px; border-radius: 20px; pointer-events: none; visibility: hidden; }
#menu.open { visibility: visible; pointer-events: auto; } #menu.closing { visibility: visible; pointer-events: none; }
#menu .backdrop { position: absolute; inset: 0; border-radius: 20px; background: rgba(23, 22, 21, .97); box-shadow: 0 0 0 1px #302f2c, 0 18px 48px rgba(0,0,0,.55); z-index: -1; }
.tile { position: relative; border-radius: var(--tile-r); background: var(--tile-texture), var(--tile); cursor: pointer; overflow: hidden; display: grid; place-items: center; outline: none; will-change: transform, opacity;
  --on: color-mix(in srgb, var(--tc) 75%, #8a8f96); --off: #302f2c; color: var(--ink); user-select: none; touch-action: none;
  transition: box-shadow 120ms, translate 160ms cubic-bezier(.2,.9,.3,1.3), scale 160ms cubic-bezier(.2,.9,.3,1.3); }
.tile.hot { scale: 1.03; } .tile:active { scale: .96; }
.tile:hover, .tile.hot { background-color: #282624; box-shadow: inset 0 0 0 1px #393835; color: #d4d7dc; }
.tile:focus-visible { box-shadow: inset 0 0 0 1.5px var(--on); }
.tile svg { width: 22px; height: 22px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }
.tile .ico { position: absolute; top: 20px; left: 0; right: 0; display: flex; justify-content: center; }
.tile .foot { position: absolute; left: 12px; right: 12px; bottom: 14px; display: flex; justify-content: center; align-items: center; gap: 6px; font: 500 12px/1 -apple-system, sans-serif; color: var(--ink-dim); font-variant-numeric: tabular-nums; }
.tile .foot.small { font-size: 11px; }
.tile.dim svg { color: #565451; }
.tile.off { cursor: default; opacity: .4; }
.bar { height: 4px; border-radius: 2px; background: var(--off); flex: 1; overflow: hidden; } .bar span { display: block; height: 100%; background: var(--on); border-radius: 2px; }
.pan { height: 4px; border-radius: 2px; background: var(--off); flex: 1; position: relative; } .pan span { position: absolute; top: -4px; width: 4px; height: 12px; margin-left: -2px; border-radius: 3px; background: var(--on); }
.dots { display: flex; gap: 3px; flex: 1; } .dots i { flex: 1; height: 4px; border-radius: 2px; background: var(--off); } .dots i.sel { background: var(--on); }
.vbar { position: absolute; right: 10px; top: 14px; bottom: 14px; width: 3px; border-radius: 2px; background: var(--off); overflow: hidden; } .vbar span { position: absolute; left: 0; right: 0; bottom: 0; background: var(--on); }
.tile .warn { position: absolute; inset: auto 8px 10px; text-align: center; font: 500 11px/1.2 -apple-system, sans-serif; color: #e0a0a0; }
.split { position: absolute; inset: 0; display: grid; grid-template-columns: 1fr 1fr; }
.split button { all: unset; display: grid; place-items: center; font: 600 15px/1 -apple-system, sans-serif; color: var(--ink-dim); cursor: pointer; }
.split button + button { box-shadow: inset 1px 0 0 #302f2c; }
.split button.on { color: #e9ebee; background: color-mix(in srgb, var(--tc) 35%, #201f1d); }
.tile.center { background-color: #191817; box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--tc) 30%, #302f2c); }
.tile.center canvas { position: absolute; inset: 12px 10px 30px; width: calc(100% - 20px); height: calc(100% - 42px); }
.tile.center .foot { font-size: 11px; font-weight: 500; left: 8px; right: 8px; overflow: hidden; white-space: nowrap; }
.tile.center.playing { box-shadow: inset 0 0 0 1.5px var(--on); }
.tile canvas.mini { position: absolute; left: 8px; right: 8px; bottom: 12px; width: calc(100% - 16px); height: 28px; }

/* Row menu title: the row's name, click to rename. */
#mname { grid-column: 1 / -1; height: 26px; margin: 0 2px -2px; padding: 0 8px; border: 1px solid transparent; border-radius: 6px; background: transparent;
  font: 600 13px/1 -apple-system, sans-serif; color: color-mix(in srgb, var(--tc) 65%, #d4d7dc); cursor: text; }
#mname:hover { border-color: #302f2c; } #mname:focus { outline: none; border-color: color-mix(in srgb, var(--tc) 50%, #302f2c); background: #201f1d; }
#menu.titled { grid-template-rows: auto repeat(3, var(--tile-size)); }

/* Zoomed panel covers the 3x3, springing out of its tile. */
#zoom { position: absolute; inset: 10px; border-radius: 14px; background: var(--tile-texture), #191817; display: none; padding: 12px 14px; color: var(--ink); z-index: 2; overflow: auto;
  box-shadow: inset 0 0 0 1px #302f2c; --on: color-mix(in srgb, var(--tc) 75%, #8a8f96); --off: #302f2c; }
#zoom.open { display: flex; flex-direction: column; }
#zoom.wide { left: -140px; right: -140px; }
#menu.titled #zoom { top: 42px; } /* the slice editor needs room */
#zoom header { display: flex; align-items: center; gap: 8px; font: 600 11px/1 -apple-system, sans-serif; letter-spacing: .08em; color: var(--ink-dim); text-transform: uppercase; margin-bottom: 10px; }
#zoom header svg { width: 14px; height: 14px; fill: none; stroke: currentColor; stroke-width: 1.8; }
#zoom header .sp { flex: 1; } #zoom header button { font: 500 11px -apple-system, sans-serif; color: var(--ink); background: none; border: 1px solid var(--off); border-radius: 6px; padding: 3px 9px; letter-spacing: 0; text-transform: none; }
.chips { display: grid; gap: 6px; } .chips button { font: 500 12px -apple-system, sans-serif; color: var(--ink); background: #201f1d; border: 1px solid var(--off); border-radius: 8px; padding: 6px 6px; display: flex; justify-content: center; align-items: center; gap: 6px; min-width: 0; }
.chips button.sel { background: color-mix(in srgb, var(--tc) 22%, #201f1d); color: #eceef1; border-color: color-mix(in srgb, var(--tc) 55%, #302f2c); }
.chips button svg { width: 14px; height: 14px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; flex: none; }
.chips.list button { font-size: 12px; overflow: hidden; white-space: nowrap; text-overflow: ellipsis; display: block; text-align: left; }
.chips button.danger { color: #ff7a7a; border-color: #5a2a2a; }
.lbl2 { font: 600 10px -apple-system, sans-serif; letter-spacing: .08em; text-transform: uppercase; color: var(--ink-dim); margin: 10px 0 6px; }
.note { font-size: 11px; color: var(--ink-dim); margin: 6px 0 0; }
#zoom canvas.prev { width: 100%; height: 56px; border-radius: 8px; background: #060605; flex: none; }
/* Panel footer: preview + "more below" hint (shown with a fade while content is under the fold). */
.zfoot { position: sticky; bottom: -12px; margin: auto -14px -12px; padding: 8px 14px 10px; display: flex; align-items: center; gap: 8px; background: #191817; border-top: 1px solid #282725; }
.zfoot::before { content: ''; position: absolute; left: 0; right: 0; bottom: 100%; height: 26px; background: linear-gradient(transparent, #191817); pointer-events: none; opacity: 0; transition: opacity 150ms; }
#zoom.more .zfoot::before { opacity: 1; }
.more-hint { font-size: 11px; color: var(--ink-dim); opacity: 0; transition: opacity 150ms; } #zoom.more .more-hint { opacity: 1; }
.zfoot button { margin-left: auto; display: flex; align-items: center; gap: 6px; font: 500 12px -apple-system, sans-serif; color: var(--ink); background: #201f1d; border: 1px solid #302f2c; border-radius: 8px; padding: 5px 12px; }
.zfoot button svg { width: 11px; height: 11px; color: var(--on); }
.zfoot button.playing { border-color: var(--on); color: #eceef1; }

/* Advanced EQ (eqedit.ts) */
.eqhost { position: relative; height: 154px; flex: none; border-radius: 8px; background: #141312; }
.eqhost canvas { position: absolute; inset: 0; width: 100%; height: 100%; cursor: crosshair; touch-action: none; }
.eqx-pop { position: absolute; display: flex; background: rgba(29, 28, 26, .97); border-radius: 8px; box-shadow: 0 0 0 1px #32312e, 0 10px 24px rgba(0,0,0,.5); overflow: hidden; z-index: 2; }
.eqx-side { display: flex; flex-direction: column; border-right: 1px solid #302f2c; }
.eqx-side button { all: unset; width: 26px; height: 26px; display: grid; place-items: center; color: var(--ink-dim); cursor: pointer; font-size: 12px; } .eqx-side button:hover { color: var(--ink); }
.eqx-side button.on { color: var(--bc); }
.eqx-main { padding: 5px 9px 7px; min-width: 210px; }
.eqx-main select { all: unset; font: 600 12px -apple-system, sans-serif; color: var(--ink); cursor: pointer; padding: 1px 0 4px; }
.eqx-f { display: grid; grid-template-columns: 1.2fr 1fr .7fr .6fr; gap: 6px; }
.eqx-f span { display: block; color: var(--ink-dim); font-size: 10px; }
.eqx-f b { display: block; font: 500 12px/1.3 -apple-system, sans-serif; color: #dfe2e6; font-variant-numeric: tabular-nums; cursor: ns-resize; white-space: nowrap; } .eqx-f b.na { color: var(--ink-dim); cursor: default; }
.chips button.more { color: var(--ink-dim); border-style: dashed; white-space: nowrap; }
#zoom canvas.wave { width: 100%; height: 104px; border-radius: 8px; background: #060605; cursor: crosshair; flex: none; touch-action: none; }
#zoom input[type=range] { width: 100%; accent-color: var(--tc); }
.knobs { display: flex; justify-content: space-around; margin: 10px 0 4px; }
.kn { display: grid; justify-items: center; gap: 4px; } .kn b { font-size: 10px; font-weight: 500; letter-spacing: .08em; text-transform: uppercase; color: var(--ink-dim); } .kn span { font: 500 12px -apple-system, sans-serif; font-variant-numeric: tabular-nums; }
.knob { --turn: 0deg; width: 38px; height: 38px; border-radius: 50%; position: relative; cursor: ns-resize; background: var(--knob-texture), radial-gradient(circle at 35% 30%, #2e2d2a, #0d0d0c 70%); box-shadow: 0 0 0 2px var(--off), 0 4px 8px rgba(0,0,0,.6); outline: none; }
.knob:focus-visible { box-shadow: 0 0 0 2px var(--on); }
.knob i { position: absolute; left: 50%; top: 4px; width: 2px; height: 11px; margin-left: -1px; border-radius: 2px; background: var(--on); transform-origin: 50% 15px; transform: rotate(var(--turn)); }

/* Names popover (header). */
.names-wrap { position: relative; }
#names.on { color: var(--text); }
#names-pop, .pop { position: absolute; right: 0; top: calc(100% + 8px); z-index: 20; width: 320px; padding: 12px; border-radius: 10px; background: #1d1c1a; box-shadow: 0 0 0 1px #302f2c, 0 14px 36px rgba(0,0,0,.5); display: grid; gap: 8px; }
#names-pop .pop-h, .pop .pop-h { margin: 0; font-weight: 600; } #names-pop .pop-t, .pop .pop-t { margin: 0; color: var(--dim); font-size: 12px; } #names-pop .pop-t:empty { display: none; }
.pop-opt { all: unset; cursor: pointer; display: grid; gap: 2px; padding: 8px 10px; border-radius: 8px; box-shadow: inset 0 0 0 1px #302f2c; }
.pop-opt:hover { background: #252422; } .pop-opt b { font-weight: 600; font-size: 13px; } .pop-opt span { color: var(--dim); font-size: 11px; }
.pop-opt.armed { box-shadow: inset 0 0 0 1px #c25454; background: #22211f; } .pop-opt.armed b { color: #ff8a8a; }
#status .undo { margin-left: 8px; padding: 1px 8px; font-size: 12px; }
#names-pop .pop-r { display: flex; gap: 6px; flex-wrap: wrap; } #names-pop input { flex: 1; min-width: 0; }

#log { font: 11px/1.4 ui-monospace, Menlo, monospace; color: var(--faint); padding: 4px 16px; max-height: 52px; overflow: auto; border-top: 1px solid var(--line); background: var(--panel); }
#log .warn { color: #e6c35c; } #log .error { color: #ff7a7a; }
body.drag main { outline: 2px dashed var(--accent); outline-offset: -6px; }
@media (prefers-reduced-motion: reduce) { .tile { transition: none; } }

.tbtns button.frank { grid-column: 1 / -1; color: #f0c6f1; border-color: color-mix(in srgb, #b300b6 55%, #302f2c); }
.tbtns button.frank:hover:not(:disabled) { color: #fff; border-color: #b300b6; }

/* ---- Splash: the tester's shop video (img/splash-bg.mp4), anchored top-left so its black corner always
   holds the title and the ways in. 3 s: the art fades up and drifts, the weld sparks flicker, the
   title and buttons arrive. ---- */
#splash { position: fixed; inset: 0; z-index: 100; overflow: hidden; background: #070707; color: #ece6da; }
#splash[hidden] { display: none; }
#splash .sp-stage { position: absolute; left: 0; top: 0; width: max(calc(100 * var(--vw, 1vw)), calc(calc(100 * var(--vh, 1vh)) * 1672 / 941)); aspect-ratio: 1672 / 941; container-type: inline-size; }
#splash .sp-bg { position: absolute; inset: 0; width: 100%; height: 100%; display: block; transform-origin: 70% 40%; animation: sp-bg 3s cubic-bezier(.2,.7,.2,1) both; }
@keyframes sp-bg { from { opacity: 0; transform: scale(1.06); filter: brightness(.4) saturate(.6); } 40% { opacity: 1; } to { opacity: 1; transform: scale(1); filter: none; } }
/* The welding sparks (on the robot's chest), flickering. */
#splash .sp-glow { position: absolute; left: 67.9%; top: 36.1%; width: 7cqw; height: 7cqw; margin: -3.5cqw 0 0 -3.5cqw; border-radius: 50%; pointer-events: none; mix-blend-mode: screen;
  background: radial-gradient(circle, rgba(255,190,120,.95) 0%, rgba(255,110,40,.55) 22%, rgba(255,80,20,0) 65%); opacity: 0; animation: sp-weld 1.7s .8s infinite steps(1, end); }
@keyframes sp-weld { 0% { opacity: .9; transform: scale(1); } 7% { opacity: .35; } 13% { opacity: 1; transform: scale(1.15); } 21% { opacity: .5; } 34% { opacity: .95; transform: scale(.9); } 48% { opacity: .2; } 55% { opacity: .85; transform: scale(1.1); } 70% { opacity: .1; } 78% { opacity: .7; } 100% { opacity: .9; transform: scale(1); } }
#splash .sp-panel { position: absolute; left: 3.6%; top: 4.5%; width: 27%; display: grid; gap: 1.1cqw; }
#splash .sp-title { margin: 0; font: 400 5.6cqw/0.95 Didot, "Bodoni 72", "Bodoni MT", "Libre Bodoni", Georgia, serif; letter-spacing: -.01em; color: #f2ece0;
  opacity: 0; animation: sp-rise 900ms 1.2s cubic-bezier(.2,.8,.2,1) forwards; }
#splash .sp-title em { font-style: italic; color: #f05a28; }
#splash .sp-tag { margin: 0 0 .8cqw; font: 500 max(10px, .72cqw)/1.3 -apple-system, sans-serif; letter-spacing: .32em; text-transform: uppercase; color: #9c958a;
  opacity: 0; animation: sp-rise 700ms 1.7s cubic-bezier(.2,.8,.2,1) forwards; }
#splash .sp-actions { display: grid; border-top: 1px solid rgba(242,236,224,.16); opacity: 0; transform: translateY(6px); pointer-events: none; transition: opacity 500ms, transform 500ms; }
#splash.ready .sp-actions { opacity: 1; transform: none; pointer-events: auto; }
#splash .sp-actions button { all: unset; cursor: pointer; display: grid; grid-template-columns: 1fr; gap: .25cqw; padding: max(9px, .85cqw) 0; border-bottom: 1px solid rgba(242,236,224,.16); position: relative; transition: padding 160ms; }
#splash .sp-actions button::after { content: '→'; position: absolute; right: 0; top: 50%; transform: translateY(-50%); color: #f05a28; opacity: 0; transition: opacity 160ms, right 160ms; font-size: max(13px, 1cqw); }
#splash .sp-actions button:hover:not(:disabled), #splash .sp-actions button:focus-visible { padding-left: .6cqw; }
#splash .sp-actions button:hover:not(:disabled)::after, #splash .sp-actions button:focus-visible::after { opacity: 1; right: .3cqw; }
#splash .sp-actions button:disabled { opacity: .35; cursor: default; }
#splash .sp-actions b { font: 400 max(15px, 1.5cqw)/1.1 Didot, "Bodoni 72", Georgia, serif; color: #f2ece0; }
#splash .sp-actions button:hover:not(:disabled) b { color: #fff; }
#splash .sp-actions span { font: 400 max(11px, .78cqw)/1.35 -apple-system, sans-serif; color: #8f897f; }
#splash #sp-list { max-height: min(17cqw, calc(30 * var(--vh, 1vh))); overflow: auto; display: grid; align-content: start; gap: 2px; padding: 6px; margin-top: -.4cqw; border-radius: 8px; background: rgba(7,7,7,.92); box-shadow: 0 0 0 1px rgba(242,236,224,.12), 0 18px 40px rgba(0,0,0,.6); }
#splash #sp-list[hidden] { display: none; }
#splash #sp-list button { all: unset; cursor: pointer; display: grid; grid-template-columns: 1fr auto; gap: 1px 10px; padding: 6px 8px; border-radius: 6px; }
#splash #sp-list button:hover, #splash #sp-list button:focus-visible { background: rgba(242,236,224,.07); }
#splash #sp-list b { font: 500 max(12px, .85cqw)/1.3 -apple-system, sans-serif; color: #ece6da; }
#splash #sp-list span { font-size: max(10.5px, .7cqw); color: #8f897f; }
#splash #sp-list .when { grid-row: 1 / span 2; grid-column: 2; align-self: center; }
#splash #sp-list .cur b { color: #f05a28; }
#splash .sp-skip { position: absolute; right: 18px; bottom: 16px; font-size: 11px; padding: 4px 10px; color: #cfc8bb; background: rgba(0,0,0,.45); border: 1px solid rgba(242,236,224,.25); border-radius: 8px; }
#splash.ready .sp-skip { display: none; }
@keyframes sp-rise { from { opacity: 0; transform: translateY(10px); } to { opacity: 1; transform: none; } }
@media (prefers-reduced-motion: reduce) { #splash .sp-bg, #splash .sp-title, #splash .sp-tag { animation: none; opacity: 1; } #splash .sp-glow { animation: none; opacity: .7; } }

/* ---- Frankenchop in the track panel: a big regenerate button, the generations to go back to. ---- */
.kg.fkslot { align-items: center; gap: 10px; padding: 8px 12px 8px 10px; background: linear-gradient(135deg, rgba(179,0,182,.16), rgba(122,53,255,.08) 60%, #0d0d0c); box-shadow: inset 0 0 0 1px rgba(179,0,182,.35); flex: 2 1 250px; min-width: 170px; }
.fkgo { all: unset; flex: none; cursor: pointer; width: 54px; height: 54px; border-radius: 50%; display: grid; place-items: center;
  background: linear-gradient(135deg, #ff5fd2, #b300b6 55%, #7a35ff); box-shadow: 0 0 18px rgba(179,0,182,.5), inset 0 1px 0 rgba(255,255,255,.25); transition: transform 140ms, filter 140ms; }
.fkgo svg { width: 28px; height: 28px; fill: none; stroke: #fff; stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; transition: transform 500ms cubic-bezier(.2,1.2,.35,1); }
.fkgo svg .spark { fill: #fff; stroke: none; }
.fkgo:hover:not(:disabled) { filter: brightness(1.12); } .fkgo:hover:not(:disabled) svg { transform: rotate(60deg); }
.fkgo:active:not(:disabled) { transform: scale(.94); }
.fkgo:disabled { filter: grayscale(1) brightness(.6); cursor: default; box-shadow: none; }
.fkgo.busy svg, .rowbtn .rc button.fk.busy svg { animation: fk-spin 700ms linear infinite; }
@keyframes fk-spin { to { transform: rotate(360deg); } }
.fkside { display: grid; gap: 5px; min-width: 0; flex: 1; }
.fkh { font: 700 12px -apple-system, sans-serif; letter-spacing: .02em; color: #f0c6f1; }
.fkhist { display: flex; flex-wrap: wrap; gap: 4px; max-height: 48px; overflow-y: auto; scrollbar-width: none; min-width: 0; padding-bottom: 1px; }
.fkhist::-webkit-scrollbar { display: none; }
.fkhist button { flex: none; font: 600 10.5px/1 -apple-system, sans-serif; padding: 5px 7px; color: #c9b8ca; background: #191817; border: 1px solid #302f2c; border-radius: 7px; }
.fkhist button:hover { color: #fff; border-color: #6d2a6f; }
.fkhist button.on { color: #fff; background: #3a0f3b; border-color: #b300b6; box-shadow: 0 0 10px rgba(179,0,182,.35); }
.fknote { font-size: 10.5px; color: #8b7f8c; line-height: 1.3; }
.rowbtn .rc button.fk { color: #f0c6f1; } .rowbtn .rc button.fk svg { width: 11px; height: 11px; fill: none; stroke: currentColor; stroke-width: 2.4; stroke-linecap: round; display: block; }
.rowbtn .rc button.fk svg .spark { fill: currentColor; stroke: none; }

/* ---- Responsive panel: knobs and labels shrink with the panel instead of overlapping. ---- */
#dock { container-type: inline-size; container-name: dock; }
.kn2 { width: auto; min-width: var(--kw, 50px); padding: 0 2px; box-sizing: border-box; } /* as wide as its label, never narrower than the knob */
.kn2 svg { width: var(--ks, 40px); height: var(--ks, 40px); }
.kn2 .kl, .kn2 .kv { max-width: 100%; overflow: hidden; text-overflow: ellipsis; }
.kg { flex: 0 1 auto; }
.kg.fxslot { flex: 1 1 auto; min-width: 0; overflow: hidden; }
.kg .tbtns { min-width: 0; }
.kn2 .ls { display: none; }
@container dock (max-width: 1100px) { .kn2 .lf { display: none; } .kn2 .ls { display: inline; } }
@container dock (max-width: 1100px) { .kn2 { --kw: 44px; --ks: 36px; } .kn2 .kl { font-size: 10.5px; } .kg { padding-left: 4px; padding-right: 4px; } .kgl { margin: 0 3px 0 1px; } }
@container dock (max-width: 940px) { .kn2 { --kw: 40px; --ks: 32px; } .kn2 .kl { font-size: 10px; } .kn2 .kv { font-size: 9.5px; } .eqcurve { width: 64px !important; } .tbtns button { padding: 2px 5px; font-size: 10px; } .fkgo { width: 46px; height: 46px; } .fkgo svg { width: 24px; height: 24px; } }
