.rl-bar .sp { flex: 1; }
.rl-bar .rl-play { font: 700 12.5px -apple-system, sans-serif; padding: 8px 16px; border-radius: 9px; min-width: 104px; }
.rl-bar .rl-pv { display: inline-grid; grid-template-columns: auto auto; }
.rl-bar .rl-pv button { padding: 6px 12px; }
.rl-pvn { font-size: 11px; color: #7d838c; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; min-width: 0; }
.rl-bar .rl-rep, .rl-bar .rl-drop { font: 700 12.5px -apple-system, sans-serif; padding: 8px 16px; border-radius: 9px; white-space: nowrap; }
.rl-bar .rl-rep { color: #e3d2e4; background: #1b0f1c; border: 1px solid rgba(179,0,182,.6); }
.rl-bar .rl-rep:hover { color: #fff; border-color: #ff5fd2; }
.rl-bar .rl-drop { color: #11100f; background: #22e6ff; border: 1px solid #22e6ff; box-shadow: 0 0 14px rgba(34,230,255,.35); }
.rl-bar .rl-drop:hover { filter: brightness(1.1); }
@container dock (max-width: 760px) { .rl-pvn { display: none; } .rl-bar { flex-wrap: wrap; } .rlab.modal .kgroups { height: auto; flex-wrap: wrap; } }
/* Riff birth animation: over the Lab's timeline, fades out onto the take. */
.rl-time canvas.rl-anim { z-index: 2; transition: opacity 180ms ease-out; }

/* ---- Trigger keys and trigger lanes (DESIGN-triggers-and-riffs.md) ------------------------------ */
/* Keys are triggers: a label for what the hit plays (chop number, or R1… for a riff), and an edge
   tick when it sounds past its step. No waveform in the key; the length lives in the lanes. */
.key .kl { position: relative; z-index: 2; font: 700 11px/1 -apple-system, sans-serif; letter-spacing: .02em; color: rgba(0, 30, 36, .82); pointer-events: none; }
.key:not(.on) .kl { display: none; }
.key.on canvas.kw { display: none; }
.key .ktick { position: absolute; z-index: 2; right: -5px; top: 50%; width: 5px; height: 14px; margin-top: -7px; border-radius: 0 3px 3px 0; background: var(--tc); opacity: 0; pointer-events: none; }
.key.on.long .ktick { opacity: .9; }
.key.riff .kl { text-decoration: underline; text-underline-offset: 2px; }

/* The selected track opens into its lanes; switching tracks collapses one while the other opens. */
.tlanes { display: grid; grid-template-rows: 0fr; transition: grid-template-rows 220ms cubic-bezier(.2, .7, .2, 1); }
.tlanes.open { grid-template-rows: 1fr; }
.tl-in { min-height: 0; overflow: hidden; }
.tl-area { position: relative; opacity: 0; transform: translateY(-4px); transition: opacity 160ms ease, transform 160ms ease; }
.tlanes.open .tl-area { opacity: 1; transform: none; transition-delay: 70ms; }
.tl-bar { all: unset; box-sizing: border-box; position: absolute; height: 20px; border-radius: 5px; cursor: pointer; overflow: hidden;
  background: color-mix(in srgb, var(--tc) 22%, #10100f); box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--tc) 65%, transparent); }
.tl-bar:hover { background: color-mix(in srgb, var(--tc) 32%, #10100f); }
.tl-bar.riff { box-shadow: inset 0 0 0 1.5px var(--tc); }
.tl-bar.sel { box-shadow: inset 0 0 0 2px #b300b6; }
.tl-bar:focus-visible { outline: 2px solid var(--tc); outline-offset: 2px; }
.tl-bar canvas { position: absolute; inset: 0; width: 100%; height: 100%; }
.tl-bar span { position: absolute; left: 5px; top: 0; font: 700 10px/20px -apple-system, sans-serif; color: color-mix(in srgb, var(--tc) 75%, #fff); text-shadow: 0 0 3px #000; pointer-events: none; }
.tl-more { position: absolute; font: 600 11px/20px -apple-system, sans-serif; color: #8a9099; }
.tl-over { position: absolute; width: 12px; height: 20px; border: 1px dashed var(--tc); border-left: 0; border-radius: 0 5px 5px 0; opacity: .7; pointer-events: none; }

/* The opened trigger's options, unfolded right under its bar: the plain chop, each riff, and
   Generate riff (the Riff Lab, aimed at this step). Clicking an option uses it at once. */
.rlab .rl-step { font: 600 12px -apple-system, sans-serif; color: #060605; background: var(--tc, #22e6ff); border: 0; border-radius: 8px; padding: 7px 14px; cursor: pointer; }
@media (prefers-reduced-motion: reduce) { .tlanes, .tl-area { transition: none; }  }

/* ==== Splash, video version: the shop video fills the card and its neon sign is the title, so the
   menu sits in the dark wall under the sign, in one modern sans serif (no Didot). ==== */
#splash { --sp-sans: "SF Pro Display", -apple-system, BlinkMacSystemFont, "Inter", "Helvetica Neue", sans-serif; }
#splash .sp-stage { aspect-ratio: 16 / 9; width: min(1100px, calc(88 * var(--vw, 1vw)), calc(calc(88 * var(--vh, 1vh)) * 16 / 9)); }
#splash .sp-bg { object-fit: cover; background: #070707; animation-duration: 1.6s; }
#splash .sp-stage::after { content: ''; position: absolute; inset: 0; pointer-events: none;
  background: linear-gradient(90deg, rgba(4, 4, 4, .62) 0%, rgba(4, 4, 4, .35) 30%, rgba(4, 4, 4, 0) 50%); }
#splash .sp-panel { z-index: 1; left: 4.6%; top: 31%; width: 29%; gap: .9cqw; font-family: var(--sp-sans); }
#splash .sp-tag { font: 600 max(10px, .7cqw)/1.3 var(--sp-sans); letter-spacing: .28em; color: #f0a35e; text-shadow: 0 0 12px rgba(240,120,40,.35); margin: 0 0 .6cqw; }
#splash .sp-actions { border-top-color: rgba(255,255,255,.12); }
#splash .sp-actions button { border-bottom-color: rgba(255,255,255,.12); }
#splash .sp-actions b { font: 600 max(15px, 1.42cqw)/1.15 var(--sp-sans); letter-spacing: -.015em; color: #f4f1ec; }
#splash .sp-actions span { font: 400 max(11px, .76cqw)/1.35 var(--sp-sans); color: #9a958f; }
#splash .sp-actions button::after { color: #ff8a3d; }
#splash #sp-list b, #splash #sp-list span { font-family: var(--sp-sans); }
#splash #sp-list .cur b { color: #ff8a3d; }
#splash .sp-skip { font-family: var(--sp-sans); }
/* A small card (narrow window): titles only, a wider column, so the menu never clips. */
@container (max-width: 760px) {
  #splash .sp-panel { width: 40%; top: 29%; }
  #splash .sp-actions span { display: none; }
  #splash .sp-actions button { padding: 7px 0; }
  #splash .sp-actions b { font-size: 14px; }
  #splash .sp-tag { letter-spacing: .2em; }
}
/* Full window: the video covers the whole window (no card). The stage is the video's 16:9 box, sized
   to cover and pinned top-left, so the sign and the menu under it never crop; any crop is on the right
   or bottom. */
#splash { display: block; background: #070707; -webkit-backdrop-filter: none; backdrop-filter: none; }
#splash .sp-stage { position: absolute; left: 0; top: 0; width: max(calc(100 * var(--vw, 1vw)), calc(calc(100 * var(--vh, 1vh)) * 16 / 9)); aspect-ratio: 16 / 9; border-radius: 0; box-shadow: none; }

/* ==== Keys v3: the tester's key sheet (img/key-{off,on,sel}[-ph].png, sliced from one sheet with the
   glow kept as transparency). off = empty, on = a trigger, sel = the selected step; -ph = the playhead
   column. The art is drawn in ::before, larger than the key, so the frame fills the cell and the glow
   spills past it. Same art on every track. ==== */
.key, .key.on, .key:not(.on).ph, .key.on.ph, .key:hover:not(.nosample), .key.on:hover:not(.nosample) { background: none; filter: none; }
.key.sel { outline: none; }
.key::before { content: ''; position: absolute; z-index: 0; inset: -11.1% -8.3%; pointer-events: none; background: url(img/key-off.png?v=mwpj9o89) center / 100% 100% no-repeat; transition: filter 80ms; }
.key.ph::before { background-image: url(img/key-off-ph.png?v=mwpj9o89); }
.key.on::before { background-image: url(img/key-on.png?v=mwpj9o89); }
.key.on.ph::before { background-image: url(img/key-on-ph.png?v=mwpj9o89); }
.key.sel::before { background-image: url(img/key-sel.png?v=mwpj9o89); }
.key.sel.ph::before { background-image: url(img/key-sel-ph.png?v=mwpj9o89); }
.key:hover:not(.nosample)::before { filter: brightness(1.18); }
.row.muted .key.on::before { filter: saturate(.3) brightness(.7); }
.key .kl { color: rgba(226, 240, 244, .82); margin-top: 14%; text-shadow: 0 1px 2px rgba(0, 0, 0, .6); }
.key.sel .kl { color: rgba(250, 226, 252, .9); }
.key.open { outline: none; }
/* Load every state up front, so the playhead never flickers on its first pass. */
body::after { content: ''; position: absolute; width: 0; height: 0; overflow: hidden; pointer-events: none;
  background: url(img/key-off-ph.png?v=mwpj9o89), url(img/key-on.png?v=mwpj9o89), url(img/key-on-ph.png?v=mwpj9o89), url(img/key-sel.png?v=mwpj9o89), url(img/key-sel-ph.png?v=mwpj9o89); }

/* Per-track key colour (tester's pick: a hue blend). A layer of the track colour (.ktint), blended
   with `hue` and masked to the key art, so the grey body stays grey and only the cyan rim and glow
   take the track's hue, keeping their brightness and shape. The selected (magenta) key isn't tinted.
   Back out: remove class="keytint" from <body>. (Not ::after: the pending dot uses it.) */
.key .ktint { display: none; }
.keytint .key .ktint { display: block; position: absolute; z-index: 1; inset: -11.1% -8.3%; pointer-events: none;
  background: var(--tc); mix-blend-mode: hue;
  -webkit-mask: url(img/key-off.png?v=mwpj9o89) center / 100% 100% no-repeat; mask: url(img/key-off.png?v=mwpj9o89) center / 100% 100% no-repeat; }
.keytint .key.ph .ktint { -webkit-mask-image: url(img/key-off-ph.png?v=mwpj9o89); mask-image: url(img/key-off-ph.png?v=mwpj9o89); }
.keytint .key.on .ktint { -webkit-mask-image: url(img/key-on.png?v=mwpj9o89); mask-image: url(img/key-on.png?v=mwpj9o89); }
.keytint .key.on.ph .ktint { -webkit-mask-image: url(img/key-on-ph.png?v=mwpj9o89); mask-image: url(img/key-on-ph.png?v=mwpj9o89); }
.keytint .key.sel .ktint { display: none; }
.keytint .row.muted .key .ktint { opacity: .3; }

/* Trigger lanes, simplified: the selected step's sound, its cell, one info line; a chevron for all hits. */
.tl-bar { height: 22px; }
.tl-bar span { line-height: 22px; }
.tl-bar.sel { box-shadow: inset 0 0 0 1.5px color-mix(in srgb, var(--tc) 80%, #fff); background: color-mix(in srgb, var(--tc) 22%, #10100f); }
.tl-cell { position: absolute; border-radius: 7px; pointer-events: none; border: 1px dashed color-mix(in srgb, var(--tc) 55%, transparent); }
.tl-all { all: unset; position: absolute; top: 6px; display: flex; align-items: center; gap: 5px; height: 20px; padding: 0 8px 0 4px; border-radius: 6px; cursor: pointer;
  font: 600 10.5px -apple-system, sans-serif; color: #8d939b; white-space: nowrap; }
.tl-all:hover { color: #eceef1; background: #201f1d; }
.tl-all:focus-visible { outline: 2px solid var(--tc); }
.tl-all svg { width: 12px; height: 12px; transition: transform 180ms cubic-bezier(.2,.7,.2,1); }
.tl-all.on svg { transform: rotate(90deg); }
.tl-all.on { color: var(--tc); }
.tl-info { position: absolute; display: flex; align-items: center; gap: 8px; white-space: nowrap; font: 500 11px -apple-system, sans-serif; color: #9aa0a8; animation: tl-info-in 180ms ease-out; }
@keyframes tl-info-in { from { opacity: 0; transform: translateY(-3px); } to { opacity: 1; transform: none; } }
.tl-info b { color: #eceef1; font-weight: 600; }
.tl-info .dim { color: #73706b; }
.tl-gen, .tl-chop { all: unset; display: inline-flex; align-items: center; gap: 5px; height: 22px; padding: 0 9px; border-radius: 6px; cursor: pointer; font: 600 11px -apple-system, sans-serif; }
.tl-gen { color: #ffd9f6; background: #2a1430; box-shadow: inset 0 0 0 1px rgba(179,0,182,.6); }
.tl-gen:hover { background: #3a1a42; color: #fff; }
.tl-gen svg { width: 13px; height: 13px; fill: none; stroke: currentColor; stroke-width: 1.6; } .tl-gen svg .spark { fill: currentColor; stroke: none; }
.tl-chop { color: #c4c8ce; background: #1d1c1a; box-shadow: inset 0 0 0 1px #302f2c; }
.tl-chop:hover { color: #fff; background: #252422; }
.tl-gen:focus-visible, .tl-chop:focus-visible { outline: 2px solid var(--tc); outline-offset: 1px; }
@media (prefers-reduced-motion: reduce) { .tl-info { animation: none; } .tl-all svg { transition: none; } }

/* ==== Mix notes: a quiet strip at the bottom with a short read of the mix and its band shape. ==== */
#mixnotes { margin: 14px 0 6px; padding: 10px 14px 12px; border-radius: 12px; background: #141312; box-shadow: inset 0 0 0 1px #252422; }
#mixnotes[hidden] { display: none; }
#mixnotes .mn-head { display: flex; align-items: center; gap: 10px; font: 600 11px -apple-system, sans-serif; color: #8d939b; letter-spacing: .02em; }
#mixnotes .mn-head b { color: #eceef1; font-size: 11.5px; letter-spacing: .06em; text-transform: uppercase; }
#mixnotes .mn-by { color: #73706b; font-weight: 500; }
#mixnotes .mn-bands { margin-left: auto; display: flex; gap: 4px; align-items: flex-end; height: 26px; }
#mixnotes .mn-bands i { position: relative; width: 26px; height: 100%; display: flex; flex-direction: column; justify-content: flex-end; align-items: center; cursor: default; }
#mixnotes .mn-bands s { display: block; width: 14px; border-radius: 2px 2px 1px 1px; background: #403e3b; transition: height 300ms cubic-bezier(.2,.7,.2,1); }
#mixnotes .mn-bands i.hot s { background: #ffb547; box-shadow: 0 0 8px rgba(255,181,71,.45); }
#mixnotes .mn-bands em { position: absolute; bottom: -12px; font: 500 8.5px -apple-system, sans-serif; font-style: normal; color: #73706b; white-space: nowrap; }
#mixnotes .mn-bands { margin-bottom: 10px; }
#mixnotes #mn-refresh { all: unset; cursor: pointer; width: 22px; height: 22px; display: grid; place-items: center; border-radius: 6px; color: #8d939b; font-size: 13px; }
#mixnotes #mn-refresh:hover { background: #201f1d; color: #eceef1; }
#mixnotes #mn-refresh:focus-visible { outline: 2px solid var(--accent, #22e6ff); }
#mixnotes.thinking #mn-refresh { animation: mn-spin 900ms linear infinite; }
@keyframes mn-spin { to { transform: rotate(360deg); } }
#mixnotes .mn-text { margin-top: 4px; display: grid; gap: 3px; }
#mixnotes .mn-text p { margin: 0; font: 400 12.5px/1.45 -apple-system, sans-serif; color: #c4c8ce; }
#mixnotes .mn-text p:first-child { color: #eceef1; font-weight: 500; }
@media (prefers-reduced-motion: reduce) { #mixnotes.thinking #mn-refresh { animation: none; opacity: .5; } #mixnotes .mn-bands s { transition: none; } }

/* Riff triggers (a step playing one of its riffs) wear the selected key's fuchsia, not the track
   colour, on the grid and in the lane. A selected riff key also gets a thin white ring, so "selected"
   and "riff" stay tellable apart. */
.key.on.riff::before { background-image: url(img/key-sel.png?v=mwpj9o89); }
.key.on.riff.ph::before { background-image: url(img/key-sel-ph.png?v=mwpj9o89); }
.keytint .key.riff .ktint { display: none; }
.key.riff .kl { color: rgba(250, 226, 252, .92); }
.key.riff .ktick { background: #e455f0; }
.key.riff.sel { outline: 1.5px solid rgba(255, 255, 255, .8); outline-offset: 2px; border-radius: 10px; }
.tl-bar.riff { --tc: #e455f0; }
.tl-info .riffname { color: #f4a8fb; }

/* The Riff Lab sub-button, right under the selected step's bar and as wide as it. */
.tl-make { all: unset; box-sizing: border-box; position: absolute; height: 22px; display: flex; align-items: center; justify-content: center; gap: 6px; padding: 0 10px;
  border-radius: 0 0 7px 7px; cursor: pointer; white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
  font: 600 11px -apple-system, sans-serif; color: #ffd9f6; background: linear-gradient(180deg, #2a1430, #22102a); box-shadow: inset 0 0 0 1px rgba(228,85,240,.55);
  animation: tl-make-in 200ms cubic-bezier(.2,.7,.2,1); transform-origin: top; }
@keyframes tl-make-in { from { opacity: 0; transform: scaleY(.6); } to { opacity: 1; transform: none; } }
.tl-make:hover { background: linear-gradient(180deg, #3a1a42, #2c1336); color: #fff; box-shadow: inset 0 0 0 1px #e455f0, 0 0 12px rgba(228,85,240,.3); }
.tl-make:focus-visible { outline: 2px solid #e455f0; outline-offset: 1px; }
.tl-make svg { width: 13px; height: 13px; flex: none; fill: none; stroke: currentColor; stroke-width: 1.6; } .tl-make svg .spark { fill: currentColor; stroke: none; }
.tl-bar.sel { border-radius: 5px 5px 0 0; }
.tl-info { animation: none; }
@media (prefers-reduced-motion: reduce) { .tl-make { animation: none; } }

/* A step LUNA hasn't taken the latest edit for (after several tries): amber corner, still retrying. */
.key.stale::after { content: ''; position: absolute; z-index: 3; right: 5px; top: 5px; width: 6px; height: 6px; border-radius: 50%; background: #ffb547; box-shadow: 0 0 6px #ffb547; animation: stale-pulse 1.2s ease-in-out infinite; }
@keyframes stale-pulse { 50% { opacity: .35; } }
#lat.catching { color: #ffb547; }
@media (prefers-reduced-motion: reduce) { .key.stale::after { animation: none; } }

/* ==== Pads: a mini copy of the user's MIDI controller under the grid. ==== */
#pads { margin: 10px 0 0; padding: 10px 12px 12px; border-radius: 12px; background: #141312; box-shadow: inset 0 0 0 1px #252422; }
#pads[hidden] { display: none; }
.pd-head { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; font: 600 11px -apple-system, sans-serif; color: #8d939b; }
.pd-head > b { color: #eceef1; font-size: 11.5px; letter-spacing: .06em; text-transform: uppercase; }
.pd-trk { color: #c4c8ce; font-weight: 600; }
.pd-dev { font: 600 11px -apple-system, sans-serif; color: #eceef1; background: #1d1c1a; border: 0; box-shadow: inset 0 0 0 1px #302f2c; border-radius: 6px; padding: 3px 6px; }
.pd-midi { font-weight: 500; color: #73706b; max-width: 380px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.pd-midi.live { color: #6be38a; }
.pd-head .sp { flex: 1; }
.pd-head button:not([data-pmode]) { all: unset; cursor: pointer; padding: 3px 9px; border-radius: 6px; color: #c4c8ce; background: #1d1c1a; box-shadow: inset 0 0 0 1px #302f2c; font: 600 11px -apple-system, sans-serif; }
.pd-head button:not([data-pmode]):hover { color: #fff; background: #252422; }
.pd-head .pd-rec.on { color: #fff; background: #5a1414; box-shadow: inset 0 0 0 1px #ff4d4d; }
.pd-head .pd-learn.on, .pd-head .pd-leds.on { color: #fff; box-shadow: inset 0 0 0 1px var(--accent, #22e6ff); }
.pd-head .pd-x { padding: 3px 7px; }
.pd-body { display: flex; gap: 16px; align-items: flex-start; margin-top: 10px; }
.pd-side { flex: 1; min-width: 160px; }
.pd-hint { margin: 0 0 6px; font: 400 11.5px/1.45 -apple-system, sans-serif; color: #9aa0a8; }
.pd-hint.dim { color: #73706b; }
.pd-empty { margin-top: 10px; font: 400 12px -apple-system, sans-serif; color: #73706b; }
/* Pad grid: drawn like the hardware (body, pad colour, corner radius from the profile). */
.pd-grid { display: grid; grid-template-columns: repeat(var(--cols), 34px); grid-auto-rows: 34px; gap: 5px; padding: 10px; border-radius: 10px; background: var(--body); box-shadow: inset 0 0 0 1px #2d2c2a, 0 8px 24px rgba(0,0,0,.4); }
.pd-pad { all: unset; position: relative; box-sizing: border-box; border-radius: var(--rad); background: var(--pad); box-shadow: inset 0 1px 0 rgba(255,255,255,.04), inset 0 -2px 0 rgba(0,0,0,.35); cursor: pointer; display: grid; place-items: center;
  font: 700 10.5px -apple-system, sans-serif; color: rgba(255,255,255,.35); transition: background 120ms, box-shadow 120ms; }
.pd-pad.on { background: color-mix(in srgb, var(--tc) 28%, var(--pad)); color: color-mix(in srgb, var(--tc) 70%, #fff); box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--tc) 55%, transparent), inset 0 -2px 0 rgba(0,0,0,.35); }
.pd-pad.on.root { background: color-mix(in srgb, var(--tc) 48%, var(--pad)); color: #fff; }
.pd-pad em { position: absolute; right: 3px; bottom: 1px; font: 600 8px -apple-system, sans-serif; font-style: normal; color: rgba(255,255,255,.28); }
.pd-pad.learn { box-shadow: inset 0 0 0 2px var(--accent, #22e6ff); animation: stale-pulse 1s ease-in-out infinite; }
.pd-pad:focus-visible, .pd-key:focus-visible { outline: 2px solid var(--tc); outline-offset: 1px; }
.pd-pad.hit, .pd-key.hit { animation: pd-hit 260ms ease-out; }
@keyframes pd-hit { 0% { background: var(--tc); box-shadow: 0 0 16px var(--tc); color: #000; } 100% { } }
/* Keyboard: white keys 22 px + 2 px gap, black keys absolutely over the gaps. */
.pd-keys { position: relative; box-sizing: content-box; height: 96px; padding: 8px; border-radius: 10px; background: #171615; box-shadow: inset 0 0 0 1px #2d2c2a, 0 8px 24px rgba(0,0,0,.4); }
.pd-key { all: unset; position: absolute; top: 8px; box-sizing: border-box; cursor: pointer; display: flex; align-items: flex-end; justify-content: center; padding-bottom: 5px; font: 700 9.5px -apple-system, sans-serif; margin-left: 8px; }
.pd-key.wht { width: 22px; height: 96px; border-radius: 0 0 4px 4px; background: #e9e9ea; color: #575551; }
.pd-key.blk { width: 16px; height: 58px; z-index: 1; border-radius: 0 0 3px 3px; background: #1f1e1c; color: #aaa; box-shadow: 0 2px 3px rgba(0,0,0,.5); }
.pd-key.wht.on { background: color-mix(in srgb, var(--tc) 35%, #e9e9ea); color: #111; }
.pd-key.blk.on { background: color-mix(in srgb, var(--tc) 55%, #1f1e1c); color: #fff; }
.pd-key.root { box-shadow: inset 0 -5px 0 var(--tc); }
@media (prefers-reduced-motion: reduce) { .pd-pad.hit, .pd-key.hit, .pd-pad.learn { animation: none; } }

/* The Riff Lab's riff view sits in a weld-gold frame: the brand's welded box. */
.rlab .rl-time { box-shadow: inset 0 0 0 1px rgba(255, 181, 71, .38), 0 0 18px rgba(255, 138, 30, .10); border-radius: 8px; }

/* ==== Riff region: a trigger riff's 16th slots in the lane, and its span on the keys. ==== */
.tl-slot { all: unset; box-sizing: border-box; position: absolute; z-index: 2; height: 22px; border-radius: 4px; cursor: pointer;
  display: flex; align-items: flex-start; justify-content: flex-end; padding: 1px 3px; font: 700 9px/1 -apple-system, sans-serif; color: #fff;
  background: rgba(228, 85, 240, .16); box-shadow: inset 0 0 0 1px rgba(228, 85, 240, .7); transition: background 100ms; }
.tl-slot:hover { background: rgba(228, 85, 240, .32); }
.tl-slot.muted { background: repeating-linear-gradient(135deg, rgba(11, 10, 9, .82) 0 4px, rgba(11, 10, 9, .6) 4px 8px); box-shadow: inset 0 0 0 1px rgba(228, 85, 240, .3); color: #8a6a8e; }
.tl-slot:focus-visible { outline: 2px solid #e455f0; outline-offset: 1px; }
/* On the grid: the keys a riff covers sit on a fuchsia rail; slots with hits get a dot on it. */
.key .krail { display: none; position: absolute; z-index: 2; left: -6px; right: -6px; bottom: -7px; height: 2px; pointer-events: none; background: rgba(228, 85, 240, .5); }
.key.inriff .krail { display: block; }
.key.riffhit .krail::after { content: ''; position: absolute; left: 50%; top: -2px; width: 6px; height: 6px; margin-left: -3px; border-radius: 50%; background: #e455f0; box-shadow: 0 0 6px #e455f0; }

/* Assign to steps: the Lab's main way out at track level (weld gold); Add as new track steps back. */
.rl-bar .rl-assign { font: 700 12.5px -apple-system, sans-serif; padding: 8px 16px; border-radius: 9px; white-space: nowrap; cursor: pointer;
  color: #1a0d00; background: linear-gradient(180deg, #ffd36b, #ff9a2a); border: 1px solid #ffc94a; box-shadow: 0 0 14px rgba(255, 154, 42, .35); }
.rl-bar .rl-assign:hover { filter: brightness(1.08); box-shadow: 0 0 18px rgba(255, 154, 42, .5); }
.rl-bar .rl-assign ~ * { }
.rl-bar .rl-drop:has(+ .rl-assign) { color: #c4c8ce; background: #1d1c1a; border-color: #302f2c; box-shadow: none; }

/* ==== The dial (tester's art): bezel, horseshoe (SVG), knob body (fixed), indicator (turns). ==== */
.kdial { position: relative; display: block; flex: none; width: var(--ks, 40px); height: var(--ks, 40px); }
.kdial .kbz { position: absolute; inset: 7.5%; border-radius: 50%;
  background: radial-gradient(circle at 50% 40%, #33322f 0%, #292826 60%, #1e1d1b 86%, #161514 100%);
  box-shadow: inset 0 1px 1px rgba(255,255,255,.06), inset 0 -3px 8px rgba(0,0,0,.5), 0 4px 10px rgba(0,0,0,.45); }
.kdial svg, .kn2 .kdial svg { position: absolute; inset: 0; width: 100%; height: 100%; overflow: visible; }
.kdial .trk { fill: none; stroke: #141312; stroke-width: 4.8; stroke-linecap: round; }
.kdial .glow { fill: none; stroke: var(--tc); stroke-width: 6.4; stroke-linecap: round; opacity: .55; filter: url(#kdial-blur); }
.kdial .val { fill: none; stroke: var(--tc); stroke-width: 3.6; stroke-linecap: round; }
.kdial .core { fill: none; stroke: color-mix(in srgb, var(--tc) 45%, #fff); stroke-width: 1.2; stroke-linecap: round; opacity: .55; }
.kdial .kbody, .kdial .kptr { position: absolute; inset: 7%; width: 86%; height: 86%; pointer-events: none; }
.kdial .kbody { filter: drop-shadow(0 1px 2px rgba(0,0,0,.55)); transition: filter 120ms; }
.kdial .kptr { transform-origin: 50% 50%; }
.kn2:hover .kbody, .kn2:focus-visible .kbody, .mdial:hover .kbody, .mdial:focus-visible .kbody { filter: drop-shadow(0 1px 2px rgba(0,0,0,.55)) brightness(1.15); }
/* No ring round a focused dial (tester, 2026-11-10: only the value arc): focus brightens the knob and its arc. */
.kn2:focus-visible .k3a .glow, .mdial:focus-visible .k3a .glow { opacity: .9; }
.kn2 .glow, .kn2 .val, .kn2 .core { transition: opacity 160ms; }
.kn2.spinning .glow, .kn2.spinning .val, .kn2.spinning .core { opacity: 0; }
.kn2.off .val { stroke: #4e4d49; } .kn2.off .glow, .kn2.off .core { opacity: 0; }
.kn2.empty .kbody { opacity: .5; } .kn2.empty .kptr { opacity: .35; }
/* The 3D knob (tester, 2026-11-10; knobs.ts): the rendered sprite (.k3) and the arc floating at its cap (.k3a) take the
   flat art's place. Looks that draw the dial as a flat ring and needle hide them again and bring the flat parts back. */
.kdial .k3 { position: absolute; pointer-events: none; background: url(img/knob/knob3d.webp?v=mwpj9o89) no-repeat; transition: filter 120ms, opacity 120ms; }
.kdial:has(.k3) > :is(.kbz, .kbody, .kptr, svg:not(.k3a)) { display: none; }
.kdial .k3a path { stroke-linejoin: round; }
.kn2:hover .k3, .kn2:focus-visible .k3, .kn2.turning .k3, .mdial:hover .k3, .mdial:focus-visible .k3, .enc:hover .k3, .enc.turning .k3 { filter: brightness(1.15); }
.kn2.empty .k3 { opacity: .55; }
/* Small (the track buttons' volume): no core line; the glow is a touch softer. */
.kdial.sm .core { display: none; } .kdial.sm .glow { opacity: .4; }
.rowbtn .mdial { width: 24px; height: 24px; }
.rowbtn .mdial .kdial { width: 100%; height: 100%; }
#grid.compact .rowbtn .mdial { width: 20px; height: 20px; }
/* The fly-out menu's LFO knobs (menus.ts): the same body and indicator art. */
.knob { background: url(img/knob/body.png?v=mwpj9o89) center / 86% no-repeat, radial-gradient(circle at 50% 40%, #33322f, #1e1d1b 86%, #161514); box-shadow: 0 0 0 2px var(--off), 0 4px 8px rgba(0,0,0,.6); }
.knob i { inset: 7%; left: 7%; top: 7%; width: 86%; height: 86%; margin: 0; border-radius: 0; background: url(img/knob/pointer.png?v=mwpj9o89) center / 100% no-repeat; transform-origin: 50% 50%; }

/* ==== Track button (tester's mockup): "1 Key Press" in the track colour; volume dial, S, M as key caps.
   Off: a dark cap with a dark green S / dark red M. On: the cap lights up green / red and glows. ==== */
.rowbtn { display: grid; grid-template-rows: auto auto; align-content: center; gap: 3px; padding: 3px 8px 3px 10px; }
.rowbtn .nm { display: flex; gap: 5px; align-items: baseline; font: 700 13px/1.1 -apple-system, sans-serif; color: var(--tc); }
.rowbtn .nm .no { font-weight: 700; flex: none; }
.rowbtn .nm .nt { min-width: 0; overflow: hidden; white-space: nowrap; }
.rowbtn .rc { display: flex; align-items: center; gap: 7px; }
.rowbtn .mdial { width: 28px; height: 28px; margin: 0; }
.rowbtn .rc button.cap { all: unset; box-sizing: border-box; cursor: pointer; width: 28px; height: 26px; display: grid; place-items: center; border-radius: 5px;
  font: 800 13px/1 -apple-system, sans-serif;
  background: linear-gradient(180deg, #3e3d3a 0%, #2f2e2c 100%);
  box-shadow: inset 0 1px 0 rgba(255,255,255,.08), inset 0 -2px 0 rgba(0,0,0,.45), 0 0 0 1px #10100f, 0 0 0 3px #242321, 0 3px 5px rgba(0,0,0,.5);
  transition: background 120ms, box-shadow 160ms, color 120ms; }
.rowbtn .rc button.cap.solo { color: #1d4a26; }
.rowbtn .rc button.cap.mute { color: #5c1418; }
.rowbtn .rc button.cap:hover { background: linear-gradient(180deg, #474642 0%, #343330 100%); }
.rowbtn .rc button.cap.solo.on { color: #c8ffd2; text-shadow: 0 0 6px rgba(170,255,190,.85);
  background: linear-gradient(180deg, #4aa964 0%, #2b7c43 100%);
  box-shadow: inset 0 1px 0 rgba(255,255,255,.18), inset 0 -2px 0 rgba(0,0,0,.35), 0 0 0 1px #0d2a15, 0 0 0 3px #1a3b22, 0 0 14px rgba(70,220,110,.55); }
.rowbtn .rc button.cap.mute.on { color: #ffe0e4; text-shadow: 0 0 6px rgba(255,200,210,.85);
  background: linear-gradient(180deg, #c0363f 0%, #8c1f27 100%);
  box-shadow: inset 0 1px 0 rgba(255,255,255,.16), inset 0 -2px 0 rgba(0,0,0,.35), 0 0 0 1px #2e0b0e, 0 0 0 3px #3e1316, 0 0 14px rgba(230,60,70,.55); }
.rowbtn .rc button.cap:focus-visible { outline: 2px solid var(--tc); outline-offset: 2px; }
/* A muted track: the name dims (no strike-through now that M lights up). */
.rowbtn.muted .nm { text-decoration: none; opacity: .5; }
#grid.compact .rowbtn .nm { font-size: 11.5px; }
#grid.compact .rowbtn .mdial { width: 22px; height: 22px; }
#grid.compact .rowbtn .rc button.cap { width: 22px; height: 19px; font-size: 10.5px; border-radius: 4px; }
/* S / M caps: the tester's art (img/caps/*.png); the letters stay text. */
.rowbtn .rc button.cap, .rowbtn .rc button.cap:hover { width: 28px; height: 28px; border-radius: 6px; box-shadow: none; background: url(img/caps/off.png?v=mwpj9o89) center / 100% 100% no-repeat; }
.rowbtn .rc button.cap:hover { filter: brightness(1.15); }
.rowbtn .rc button.cap.solo.on { background: url(img/caps/solo-on.png?v=mwpj9o89) center / 100% 100% no-repeat; box-shadow: none; filter: drop-shadow(0 0 6px rgba(70, 220, 110, .5)); }
.rowbtn .rc button.cap.mute.on { background: url(img/caps/mute-on.png?v=mwpj9o89) center / 100% 100% no-repeat; box-shadow: none; filter: drop-shadow(0 0 6px rgba(230, 60, 70, .5)); }
#grid.compact .rowbtn .rc button.cap { width: 22px; height: 22px; }
/* Load both lit caps up front so the first S / M press doesn't flash. */
.rowbtn::before { content: ''; position: absolute; width: 0; height: 0; overflow: hidden; background: url(img/caps/solo-on.png?v=mwpj9o89), url(img/caps/mute-on.png?v=mwpj9o89); }
/* No added glow: the cap art carries its own. */
.rowbtn .rc button.cap.solo.on, .rowbtn .rc button.cap.mute.on { filter: none; text-shadow: none; }

/* The selected step: a white outline 1 px outside the key's frame, 1.5 px wide, its corners
   following the key art's (about 11% of the key). */
.key.sel, .key.riff.sel { outline: none; }
.key .ksel { display: none; position: absolute; z-index: 3; inset: -2.5px; box-sizing: border-box; box-shadow: inset 0 0 0 1.5px #e455f0; pointer-events: none; /* fuchsia = selection only */
  border-radius: calc(var(--cell, 40px) * 0.11 + 2.5px); }
.key.sel .ksel { display: block; }
/* S / M about 40% smaller; the Riff Lab key (an icon on a cap) at the far right of the row. */
.rowbtn .rc button.cap, .rowbtn .rc button.cap:hover, .rowbtn .rc button.cap.solo.on, .rowbtn .rc button.cap.mute.on { width: 17px; height: 17px; border-radius: 4px; font-size: 8.5px; }
.rowbtn .rc button.cap.lab { margin-left: auto; width: 24px; height: 24px; border-radius: 5px; color: #c4c8ce; }
.rowbtn .rc button.cap.lab svg { width: 13px; height: 13px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; display: block; }
.rowbtn .rc button.cap.lab svg .spark { fill: currentColor; stroke: none; }
.rowbtn .rc button.cap.lab:hover:not(:disabled) { color: #fff; }
.rowbtn .rc button.cap.lab:disabled { opacity: .35; cursor: default; filter: none; }
.rowbtn .rc button.cap.lab.busy svg { animation: fk-spin 900ms linear infinite; }
#grid.compact .rowbtn .rc button.cap { width: 15px; height: 15px; font-size: 7.5px; }
#grid.compact .rowbtn .rc button.cap.lab { width: 20px; height: 20px; }
/* The ring fits the key art's frame: the frame is 94% of the key's width (3.1% in each side) and full
   height. The "runs past the step" tab shows only on the selected key, in fuchsia, against the ring. */
.key .ksel { top: -2.5px; bottom: -2.5px; left: calc(3.1% - 2.5px); right: calc(3.1% - 2.5px); }
.key .ktick { opacity: 0; }
.key.on.long .ktick { opacity: 0; }
.key.on.sel.long .ktick { opacity: 1; background: #e455f0; right: calc(3.1% - 7.5px); width: 5px; height: 14px; margin-top: -7px; border-radius: 0 3px 3px 0; z-index: 3; }

/* ==== The Lab's key lane: the track's keys under the riff (one per 16th, lined up with it). ==== */
.rlab .rl-keys { display: flex; gap: var(--gap, 4px); justify-content: space-between; padding: 6px 0 4px; }
.rlab .rl-keys[hidden] { display: none; }
.rl-keys .key { pointer-events: none; cursor: default; }
.rl-keys .key .kl { font-size: calc(var(--cell) * 0.24); }
.rl-keys .key.ghost::before { filter: brightness(.5) saturate(.85); }
.rl-keys .key.ghost .ktint { opacity: 1; }
.rl-keys .key.ghost .kl { opacity: .6; }
/* Landing: the selection ring flashes and two rings ripple out from it (a radar ping). */
.key.burst .ksel { display: block; animation: rl-ping-ring 520ms ease-out both; }
.key.burst .ksel::before, .key.burst .ksel::after { content: ''; position: absolute; inset: -1.5px; border-radius: inherit; border: 1.5px solid #e455f0; box-sizing: border-box; background: none; animation: rl-ping 800ms cubic-bezier(.2, .7, .2, 1) both; }
.key.burst .ksel::after { animation-delay: 180ms; }
@keyframes rl-ping { from { transform: scale(1); opacity: .95; } to { transform: scale(1.75); opacity: 0; } }
@keyframes rl-ping-ring { 0% { opacity: 1; } 70% { opacity: 1; } 100% { opacity: 0; } }
/* The same burst over any control (burstOn: the header's Play when Glitchy swats it), above the tour's dim. */
.burst-fx { position: fixed; z-index: 100000; pointer-events: none; box-sizing: border-box; border: 1.5px solid #e455f0; box-shadow: 0 0 10px rgba(228, 85, 240, .55); animation: rl-ping-ring 520ms ease-out both; }
.burst-fx::before, .burst-fx::after { content: ''; position: absolute; inset: -1.5px; border-radius: inherit; border: 1.5px solid #e455f0; box-sizing: border-box; animation: rl-ping 800ms cubic-bezier(.2, .7, .2, 1) both; }
.burst-fx::after { animation-delay: 180ms; }
/* The slot above in the riff flashes as its key lands. */
.rlab .rl-time { position: relative; }
.rl-time .rl-sweep { position: absolute; top: 0; bottom: 0; z-index: 3; pointer-events: none; background: linear-gradient(180deg, rgba(228, 85, 240, 0), rgba(228, 85, 240, .28) 60%, rgba(228, 85, 240, .5)); animation: rl-sweep 650ms ease-out both; }
@keyframes rl-sweep { from { opacity: 1; } to { opacity: 0; } }
/* After Assign: Done takes you back to the track. */
.rl-bar .rl-assign.rl-done { background: linear-gradient(180deg, #4aa964, #2b7c43); border-color: #5cd17c; color: #eafff0; box-shadow: 0 0 14px rgba(70, 220, 110, .35); }
@media (prefers-reduced-motion: reduce) { .rl-keys .key.burst .ksel, .rl-keys .key.burst .ksel::before, .rl-keys .key.burst .ksel::after, .rl-time .rl-sweep { animation: none; } }
/* No scrollbar under the grid (it still scrolls sideways at 32 steps: trackpad / wheel). */
#grid .gscroll { scrollbar-width: none; }
#grid .gscroll::-webkit-scrollbar { display: none; width: 0; height: 0; }

/* ==== Pads beside the grid: a mini copy of the controller, rows lined up with the tracks. ==== */
#grid { padding-right: calc(44px + 196px); }
.pcol { position: absolute; top: 0; bottom: 0; right: 46px; z-index: 2; pointer-events: none; }
.pcol > * { pointer-events: auto; }
.pc-head { position: absolute; top: 4px; left: 0; right: 0; display: grid; gap: 3px; font: 600 10px -apple-system, sans-serif; color: #8d939b; }
.pc-dev { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; color: #73706b; }
.pc-dev.live { color: #6be38a; }
.pc-pick { font: 600 10px -apple-system, sans-serif; color: #c4c8ce; background: #1d1c1a; border: 0; box-shadow: inset 0 0 0 1px #302f2c; border-radius: 4px; padding: 1px 3px; max-width: 100%; }
.pc-row { display: flex; gap: 4px; align-items: center; }
.pc-row .tp-seg button { padding: 1px 6px; font-size: 10px; }
.pc-rec { all: unset; cursor: pointer; width: 18px; height: 16px; display: grid; place-items: center; border-radius: 4px; color: #7a2a2e; background: #1d1c1a; box-shadow: inset 0 0 0 1px #302f2c; font-size: 9px; }
.pc-rec.on { color: #ff6b74; background: #3a1214; box-shadow: inset 0 0 0 1px #ff4d58, 0 0 8px rgba(255, 77, 88, .4); }
.pc-wake { color: #ffb547; font-weight: 500; }
.pc-pads { position: absolute; left: 0; display: flex; gap: 3px; }
.pc-pad { all: unset; box-sizing: border-box; width: var(--pad); height: var(--pad); border-radius: 3px; cursor: pointer;
  background: #1e1d1b; box-shadow: inset 0 1px 0 rgba(255,255,255,.04), inset 0 -1px 0 rgba(0,0,0,.5), 0 0 0 1px #0f0f0e;
  display: grid; place-items: center; font: 700 8px/1 -apple-system, sans-serif; color: #fff; transition: background 140ms, box-shadow 140ms; }
.pc-pad.on { background: color-mix(in srgb, var(--tc) 42%, #1e1d1b); box-shadow: inset 0 1px 0 rgba(255,255,255,.12), 0 0 0 1px color-mix(in srgb, var(--tc) 50%, #0f0f0e); }
.pc-pad.on.root { background: color-mix(in srgb, var(--tc) 70%, #1e1d1b); }
.pc-pad.hit { animation: pc-hit 280ms ease-out; }
@keyframes pc-hit { 0% { background: #fff; box-shadow: 0 0 10px var(--tc), 0 0 0 1px #fff; } 100% { } }
@media (prefers-reduced-motion: reduce) { .pc-pad.hit { animation: none; } }
/* A fine divider every 4 steps (the beat), in the gap before the key; the rows' segments join up. */
.key .kdiv { position: absolute; z-index: 0; left: calc(var(--gap, 8px) / -2 - 0.25px); top: -7px; bottom: -7px; width: 0.5px; background: rgba(255, 255, 255, .13); pointer-events: none; }
/* Track button: room above the title; black S / M letters when off; S / M a little further from the volume. */
.rowbtn { align-content: start; padding-top: 7px; gap: 2px; }
.rowbtn .mdial { width: 26px; height: 26px; }
.rowbtn .rc button.cap.solo:not(.on), .rowbtn .rc button.cap.mute:not(.on) { color: #000; }
.rowbtn .rc button.cap.solo { margin-left: 6px; }
#grid.compact .rowbtn { padding-top: 4px; }

/* ==== Pads, floating: a tiny mini controller you drag around (opt in: the header's Pads button). ==== */
#grid { padding-right: 44px; }
.pfloat { position: fixed; z-index: 60; display: grid; gap: 5px; padding: 6px 7px 7px; border-radius: 9px; background: rgba(20, 19, 18, .94);
  box-shadow: 0 0 0 1px #2d2c2a, 0 12px 30px rgba(0,0,0,.55); -webkit-backdrop-filter: blur(6px); backdrop-filter: blur(6px); user-select: none; -webkit-user-select: none; }
.pfloat[hidden] { display: none; }
.pf-bar { display: flex; align-items: center; gap: 4px; cursor: grab; min-width: 0; }
.pf-bar:active { cursor: grabbing; }
.pf-dot { width: 6px; height: 6px; border-radius: 50%; background: #4e4d49; flex: none; }
.pf-dot.live { background: #6be38a; box-shadow: 0 0 5px #6be38a; }
.pf-pick { all: unset; flex: 1; min-width: 0; max-width: 64px; font: 600 9px -apple-system, sans-serif; color: #9aa0a8; cursor: pointer; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.pf-x { all: unset; cursor: pointer; font-size: 9px; color: #73706b; padding: 0 2px; } .pf-x:hover { color: #eceef1; }
.pf-grid { display: grid; grid-template-columns: repeat(var(--cols), 5px); grid-auto-rows: 5px; gap: 1.5px; justify-content: center; }
.pfloat .pc-pad { width: 5px; height: 5px; border-radius: 1.5px; box-shadow: none; background: #292826; }
.pfloat .pc-pad.on { background: color-mix(in srgb, var(--tc) 75%, #1e1d1b); box-shadow: none; }
.pfloat .pc-pad.on.root { background: var(--tc); }
.pf-row { display: flex; gap: 3px; justify-content: space-between; }
.pf-row button { all: unset; cursor: pointer; font: 600 8.5px -apple-system, sans-serif; color: #7d838c; padding: 1px 3px; border-radius: 3px; }
.pf-row button:hover { color: #eceef1; }
.pf-row button.on { color: #eceef1; background: #2d2c2a; }
.pf-row .pc-rec { width: auto; height: auto; background: none; box-shadow: none; color: #7a2a2e; }
.pf-row .pc-rec.on { color: #ff4d58; text-shadow: none; background: none; box-shadow: none; }
.pfloat .pc-wake { font: 500 8.5px -apple-system, sans-serif; color: #ffb547; text-align: center; }
#padsbtn.on { color: #eceef1; box-shadow: inset 0 0 0 1px var(--accent, #22e6ff); }
/* A selected track (its name clicked): the whole lane, button to last key, in the selection fuchsia. */
.row { position: relative; z-index: 0; }
.row.lanesel::before { content: ''; position: absolute; z-index: -1; inset: -5px -6px; border-radius: 12px; pointer-events: none;
  background: rgba(228, 85, 240, .07); box-shadow: inset 0 0 0 1.5px rgba(228, 85, 240, .8); }
.row.lanesel .rowbtn { background-color: transparent; box-shadow: none; }

/* ==== Header, simplified: left (brand, dice, swing) · centre (Stop, Play) · right (BPM, 16|32, the rest).
   The bar spans the window; it fills the window with the same 16px gutter as the grid (it used to follow a measured --appw, which went stale on resize). ==== */
header { display: grid; grid-template-columns: 1fr auto 1fr; align-items: center; gap: 6px 14px;
  padding: 10px 16px 6px; flex-wrap: nowrap; }
header > * { min-width: 0; }
.hd-left { display: flex; align-items: center; gap: 12px; justify-self: start; }
.hd-left .groove { border-left: 0; padding-left: 0; gap: 6px; }
.hd-right { display: flex; align-items: center; gap: 8px; justify-self: end; flex-wrap: nowrap; }
.hd-status { grid-column: 1 / -1; display: flex; align-items: center; justify-content: space-between; gap: 10px; min-height: 16px; font-size: 11.5px; color: var(--faint); }
.hd-status #status { flex: 1; min-width: 0; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
/* Transport: Stop and Play as the shop's key caps, dead centre. Play lights green while LUNA plays. */
header .transport { display: flex; gap: 12px; justify-self: center; padding: 0; border: 0; background: none; }
header .transport .tkey { all: unset; box-sizing: border-box; width: 44px; height: 44px; display: grid; place-items: center; cursor: pointer; color: #0c0b0a;
  background: url(img/caps/off.png?v=mwpj9o89) center / 100% 100% no-repeat; transition: filter 120ms, transform 60ms; }
header .transport .tkey svg { width: 17px; height: 17px; fill: currentColor; }
header .transport .tkey:hover { filter: brightness(1.15); }
header .transport .tkey:active { transform: translateY(1px); }
header .transport .tkey:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; border-radius: 8px; }
header .transport #play.on { background: url(img/caps/solo-on.png?v=mwpj9o89) center / 100% 100% no-repeat; color: #eaffef; border: 0; }
/* The dice: Generate chop, an icon on a cap. */
header .hd-dice { all: unset; box-sizing: border-box; width: 32px; height: 32px; display: grid; place-items: center; cursor: pointer; color: #c4c8ce;
  background: url(img/caps/off.png?v=mwpj9o89) center / 100% 100% no-repeat; }
header .hd-dice svg { width: 17px; height: 17px; fill: none; stroke: currentColor; stroke-width: 1.6; }
header .hd-dice svg circle { fill: currentColor; stroke: none; }
header .hd-dice:hover { color: #fff; filter: brightness(1.15); }
header .hd-dice.open, header .hd-dice[aria-expanded="true"] { color: #fff; }
/* 16 | 32: a quiet segmented toggle. */
header .hd-len button { padding: 3px 10px; font: 600 11.5px -apple-system, sans-serif; font-variant-numeric: tabular-nums; }
header .field.bpm input { width: 56px; text-align: center; }
/* The floating pads' name. */
.pf-name { font: 700 8.5px -apple-system, sans-serif; letter-spacing: .06em; text-transform: uppercase; color: #c4c8ce; white-space: nowrap; }
/* Header fixes: the old Generate / transport styles out of the way; no fuchsia (selection only). */
header #gen.hd-dice, header #gen.hd-dice:hover { background: url(img/caps/off.png?v=mwpj9o89) center / 100% 100% no-repeat; border: 0; box-shadow: none; padding: 0; }
header .transport [hidden] { display: none !important; } /* #tostart is the ⏮ key now (2026-10-22) */
header .transport .tkey { border: 0; box-shadow: none; margin: 0; }
header .field.bpm input { width: 68px; }
header .hd-len button.on { background: #32312e; color: #fff; box-shadow: inset 0 0 0 1px #4f4e4a; }
header .transport { box-shadow: none; }

/* Edge dials (concept, 2026-10-17): Chop start on the waveform's left edge, Length on its right.
   Faint until you hover the waveform; steps only (a track has no start/length). */
.fzoom { position: relative; }
.edials { position: absolute; inset: 0; pointer-events: none; }
.edials .kn2 { position: absolute; top: 50%; transform: translateY(-50%); pointer-events: auto; padding: 6px 6px 4px; border-radius: 12px;
  background: rgba(15, 15, 14, .82); box-shadow: 0 0 0 1px #2d2c2a, 0 6px 16px rgba(0,0,0,.45); opacity: .28; transition: opacity 160ms; }
.edials .kn2[data-kn="start"] { left: 8px; }
.edials .kn2[data-kn="length"] { right: 8px; }
.fzoom:hover .edials .kn2, .edials .kn2:focus-visible, .edials .kn2:active { opacity: 1; }
.focus.trackmode .edials, .focus.empty .edials { display: none; }

/* Edge encoders, outside the waveform (the drag bars stay free): no arc, endless, fine-tune. */
.fzoom { margin: 0 78px; }
.edials { inset: 0 -78px; }
.edials .enc { position: absolute; top: 50%; transform: translateY(-50%); pointer-events: auto; width: 66px; display: grid; justify-items: center; gap: 1px; cursor: ns-resize; outline: none; user-select: none; touch-action: none; }
.edials .enc[data-enc="start"] { left: 0; }
.edials .enc[data-enc="length"] { right: 0; }
.edials .enc .kdial { --ks: 42px; }
.edials .enc .kl { font: 500 11px/1.2 -apple-system, sans-serif; color: #c4c8ce; margin-top: 3px; white-space: nowrap; }
.edials .enc .kv { font: 500 10px/1.2 -apple-system, sans-serif; color: #7d838c; font-variant-numeric: tabular-nums; white-space: nowrap; }
.edials .enc:hover .kbody, .edials .enc.turning .kbody { filter: drop-shadow(0 1px 2px rgba(0,0,0,.55)) brightness(1.15); }
.edials .enc:focus-visible .k3 { filter: brightness(1.15); }
.edials .kn2 { display: none; }
.focus.trackmode .fzoom, .focus.empty .fzoom { margin: 0; }

/* Long sounds: the selected step's sound as a fuchsia rail under the keys it covers (wrapping round
   to step 1), with an end mark; a small ↩ on any key whose sound wraps past the pattern end. */
.key.tailcov .krail { display: block; background: rgba(228, 85, 240, .55); left: -10px; right: -10px; bottom: -8px; height: 2px; }
.key.tailend .krail { right: 40%; }
.key.tailend .krail::after { content: ''; position: absolute; right: -1px; top: -3px; width: 2px; height: 8px; border-radius: 1px; background: #e455f0; }
.key.wraps::after { content: '↩'; position: absolute; z-index: 3; right: 3px; top: 1px; font: 700 9px/1 -apple-system, sans-serif; color: rgba(255, 255, 255, .55); background: none; box-shadow: none; width: auto; height: auto; animation: none; }
/* Splash: no dark overlay over the video (it dimmed the sign); the menu reads by a soft shadow instead. */
#splash .sp-stage::after { content: none; }
#splash .sp-tag, #splash .sp-actions b, #splash .sp-actions span { text-shadow: 0 1px 2px rgba(0, 0, 0, .9), 0 0 12px rgba(0, 0, 0, .7); }

/* ==== Panel v2: two tiers, TRACK on top and STEP below; dials in a grid on the left, the view on the right. ==== */
.focus { gap: 0; }
.focus .kstep, .focus .ktrack, .focus.trackmode .kstep, .focus:not(.trackmode) .ktrack { display: block; }
.tier { display: grid; grid-template-columns: 264px minmax(0, 1fr); gap: 18px; padding: 12px 6px 14px; }
.tier + .tier { border-top: 1px solid #272624; }
.tier-l { display: grid; gap: 10px; align-content: start; min-width: 0; }
.tier-r { display: grid; gap: 8px; align-content: start; min-width: 0; }
.tier .ftitle { display: flex; align-items: baseline; gap: 8px; min-width: 0; }
.tier .ftitle b, .tier .ftitle .tname { font: 700 16px -apple-system, sans-serif; color: var(--tc); }
.tier .dgrid { display: grid; gap: 6px 4px; justify-items: center; }
.ttrack .dgrid { grid-template-columns: repeat(3, 1fr); }
.tstep .dgrid { grid-template-columns: repeat(4, 1fr); }
.tier .dgrid .kn2 { --ks: 36px; min-width: 0; width: 100%; }
.tier .kgroups .eqcurve { display: block; width: 100%; height: 26px; margin-top: 6px; }
.tier .kgroups .eqcurve canvas { width: 100%; height: 100%; }
.tier-sm { display: flex; align-items: center; gap: 6px; }
.tier-sm .cap { all: unset; box-sizing: border-box; cursor: pointer; width: 20px; height: 20px; display: grid; place-items: center; border-radius: 4px;
  font: 800 9.5px/1 -apple-system, sans-serif; color: #000; background: url(img/caps/off.png?v=mwpj9o89) center / 100% 100% no-repeat; }
.tier-sm .cap:hover { filter: brightness(1.15); }
.tier-sm .cap.solo.on { background-image: url(img/caps/solo-on.png?v=mwpj9o89); color: #eaffef; }
.tier-sm .cap.mute.on { background-image: url(img/caps/mute-on.png?v=mwpj9o89); color: #ffe6ea; }
.tier-sm .cap:disabled { opacity: .35; cursor: default; filter: none; }
.tier-sm .trackfx { margin-left: auto; }
.tier-btns { display: grid; grid-template-columns: repeat(4, 1fr); gap: 4px; }
.tier-btns button { padding: 3px 2px; font-size: 10.5px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.tier-head { display: flex; align-items: center; gap: 6px; min-height: 30px; }
.tier-lbl { font: 700 10.5px -apple-system, sans-serif; letter-spacing: .08em; text-transform: uppercase; color: #8d939b; margin-right: 6px; }
.tier-info { margin-left: auto; font: 500 11.5px -apple-system, sans-serif; color: #7d838c; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; min-width: 0; }
/* Takes (1, 2, 3 …) and the dice (Chop Shop) as key caps. */
.takes { display: flex; gap: 4px; }
.takes button, .dicecap { all: unset; box-sizing: border-box; cursor: pointer; width: 28px; height: 28px; display: grid; place-items: center; border-radius: 6px;
  font: 800 12px/1 -apple-system, sans-serif; color: #c4c8ce; background: url(img/caps/off.png?v=mwpj9o89) center / 100% 100% no-repeat; transition: filter 120ms; }
.takes button:hover, .dicecap:hover { filter: brightness(1.18); color: #fff; }
.takes button.on { color: #fff; box-shadow: 0 0 0 1.5px #e455f0; } /* the take in use: selection fuchsia */
.dicecap svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 1.6; } .dicecap svg circle { fill: currentColor; stroke: none; }
.dicecap.busy svg { animation: fk-spin 900ms linear infinite; }
.dicecap:disabled, .takes button:disabled { opacity: .35; cursor: default; filter: none; }
.flane { position: relative; }
.flane canvas.tlanec { display: block; width: 100%; border-radius: 8px; cursor: pointer; }
.tier .fxslot { display: flex; align-items: center; gap: 8px; padding: 0; background: none; box-shadow: none; }
/* No step selected: the step tier says how to get one. */
.fzoom { position: relative; min-height: 150px; }
.fz-empty { display: none; }
.focus.trackmode .fz-empty { display: grid; place-items: center; position: absolute; inset: 0; border-radius: 8px; background: #141312; color: #73706b; font: 500 12px -apple-system, sans-serif; }
.focus.trackmode .fzoom .tview { visibility: hidden; }
.focus.trackmode .tstep .dgrid, .focus.trackmode .tstep .tier-sm { opacity: .35; pointer-events: none; }
.focus.trackmode .tstep .fstrip { opacity: .6; }
.tier .kgroups { display: block; height: auto; padding: 0; margin: 0; background: none; box-shadow: none; overflow: visible; }
.tier .kgroups > .dgrid { position: static; }
/* Fewer labels (mockup): a dial shows its value; its name only when the value says nothing (Pitch at
   0 st, Retrig at ×1), and on hover. */
.tier .kn2 .kl { display: none; }
.tier .kn2.named .kl { display: block; } .tier .kn2.named .kv { display: none; }
.tier .kn2:hover .kl { display: block; } .tier .kn2:hover .kv { display: none; }
.tier .kn2 .kv { font-size: 11px; color: #9aa0a8; margin-top: 3px; }

/* Step S/M on the grid keys: a muted step dims, a soloed step carries a small S. */
.key.smute { filter: brightness(.45) saturate(.4); }
.key .kss { display: none; }
.key.ssolo .kss { display: block; font-style: normal; position: absolute; left: 6px; bottom: 5px; z-index: 4; font: 700 8px/1 -apple-system, sans-serif; color: #111; background: #f5d547; border-radius: 2px; padding: 1px 2px; pointer-events: none; }
.tier-sm .cap:disabled { opacity: .35; }

/* Inline Chop Shop dice: the weld animation over the track lane / step view, and the takes keys. */
.flane canvas.rl-anim, .fzoom canvas.rl-anim { position: absolute; inset: 0; width: 100%; height: 100%; z-index: 6; pointer-events: none; border-radius: 6px; transition: opacity 180ms ease-out; }
.takes { display: flex; gap: 4px; }
.focus.rolling .dicecap[data-dice="step"] { animation: dice-spin 700ms linear infinite; }
@keyframes dice-spin { to { transform: rotate(360deg); } }
.dicecap:disabled { opacity: .35; }

/* Step tier, v2.1 (tester, 2026-10-18): no chop strip; the step view fills the tier, and chop start /
   chop end are the last two dials in the step grid (fine-tune; the drag bars on the view set them roughly). */
.tier .fzoom { margin: 0; }
.tier .dgrid .enc { width: 100%; min-width: 0; display: grid; justify-items: center; cursor: ns-resize; outline: none; user-select: none; touch-action: none; }
.tier .dgrid .enc .kdial { --ks: 36px; }
.tier .dgrid .enc .kl, .tier .dgrid .enc .kv { font-size: 11px; color: #9aa0a8; margin-top: 3px; white-space: nowrap; font-variant-numeric: tabular-nums; }
.tier .dgrid .enc .kl { display: none; color: #c4c8ce; }
.tier .dgrid .enc.named .kl, .tier .dgrid .enc:hover .kl { display: block; }
.tier .dgrid .enc.named .kv, .tier .dgrid .enc:hover .kv { display: none; }
.tier .dgrid .enc:hover .kbody, .tier .dgrid .enc.turning .kbody { filter: brightness(1.15); }
.chopnav { display: inline-flex; align-items: center; gap: 2px; margin-right: 4px; font: 500 11.5px -apple-system, sans-serif; color: #c4c8ce; font-variant-numeric: tabular-nums; }
.chopnav[hidden] { display: none; }
.chopnav span { min-width: 58px; text-align: center; }
.chopnav button { all: unset; cursor: pointer; width: 20px; height: 24px; display: grid; place-items: center; border-radius: 5px; color: #9aa0a8; font-size: 15px; }
.chopnav button:hover { background: rgba(255,255,255,.07); color: #fff; }
.chopnav button:disabled { opacity: .3; cursor: default; }
/* The step view fills the tier's height (beside the dial grid). */
.tstep .tier-r { display: flex; flex-direction: column; }
.tstep .fzoom { flex: 1 1 auto; min-height: 150px; }
.tstep .fzoom canvas.tview { position: absolute; left: 0; top: 0; }

/* ---- Tone (template synth on the step's chop): header buttons and the drawer under the Step tier ---- */
.dicecap.tonecap svg path { stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; }
.focus.toning .tonecap { animation: dice-spin 700ms linear infinite; }
.tonebtn { all: unset; cursor: pointer; height: 28px; padding: 0 10px; border-radius: 6px; font: 600 11.5px -apple-system, sans-serif; color: #c4c8ce; background: #292826; box-shadow: inset 0 0 0 1px #383634; }
.tonebtn:hover { color: #fff; } .tonebtn.on { color: #fff; box-shadow: 0 0 0 1.5px #e455f0; }
.takes button.tone { font-style: italic; }
.tonedrawer { grid-column: 1 / -1; position: relative; display: grid; grid-template-columns: 240px minmax(0, 1fr) minmax(300px, 400px); gap: 16px; margin-top: 12px; padding: 12px; border-radius: 12px; background: #191817; box-shadow: inset 0 0 0 1px #2e2d2a; }
.tonedrawer[hidden] { display: none; }
canvas.td3 { display: block; width: 100%; border-radius: 8px; cursor: grab; background: radial-gradient(120% 90% at 50% 30%, #1e1d1b, #131211); box-shadow: inset 0 0 0 1px #252422; }
canvas.td3:active { cursor: grabbing; }
.td-l canvas.td3 { height: 170px; }
.td-cap { display: flex; justify-content: space-between; gap: 8px; margin-top: 6px; font-size: 11px; color: #7d838c; }
.td-tn { color: #c4c8ce; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.td-m { display: grid; gap: 8px; align-content: start; min-width: 0; }
.td-row { display: flex; align-items: center; gap: 6px; flex-wrap: wrap; }
.tonedrawer button:not(.kn2):not(.tl-t) { font: 500 12px -apple-system, sans-serif; color: #c4c8ce; background: #292826; border: 1px solid #383634; border-radius: 7px; padding: 5px 10px; cursor: pointer; }
.tonedrawer button:not(.kn2):not(.tl-t):hover { color: #fff; }
.tonedrawer button.on { color: #fff; box-shadow: 0 0 0 1.5px #e455f0; border-color: transparent; }
.td-slot b { color: #fff; font-weight: 600; }
.td-knobs { gap: 4px 14px; } .td-knobs .kn2 { --ks: 36px; width: 74px; }
.td-checks { display: grid; gap: 4px; font-size: 11.5px; color: #9aa0a8; }
.td-note { font-size: 11.5px; color: #7d838c; min-height: 16px; }
.td-pair { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; }
.td-pair canvas.td3 { height: 128px; }
.td-pair span { display: block; font-size: 11px; color: #7d838c; margin-top: 4px; }
.td-r { display: grid; gap: 10px; align-content: start; }
.td-r button[data-tn="roll"] svg { width: 14px; height: 14px; fill: none; stroke: currentColor; stroke-width: 1.6; vertical-align: -2px; } .td-r button[data-tn="roll"] svg circle { fill: currentColor; stroke: none; }
.tonedrawer .td-add { color: #fff !important; background: #3a1640 !important; border-color: #e455f0 !important; }
.td-sim { display: inline-flex; align-items: center; gap: 6px; font-size: 11px; color: #c4c8ce; margin-right: auto; font-variant-numeric: tabular-nums; }
.td-sim i { display: block; width: 70px; height: 5px; border-radius: 3px; background: #2e2d2a; position: relative; overflow: hidden; }
.td-sim i b { position: absolute; inset: 0 auto 0 0; background: linear-gradient(90deg, #ff6b4a, #f5d547 50%, #4dff7a); }
/* the template library: a popover over the drawer */
.td-lib { position: absolute; z-index: 20; left: 12px; right: 12px; bottom: calc(100% - 6px); max-height: 380px; overflow: auto; padding: 10px 12px 12px; border-radius: 12px; background: #201f1d; box-shadow: 0 12px 40px rgba(0,0,0,.6), inset 0 0 0 1px #383634; }
.td-lib[hidden] { display: none; }
.tl-head { display: flex; align-items: center; gap: 10px; margin-bottom: 4px; font-size: 12px; color: #7d838c; } .tl-head b { color: #eceef1; } .tl-head em { font-style: normal; color: #e455f0; font-weight: 700; } .tl-head button { margin-left: auto; }
.tl-g > span { display: block; margin: 8px 0 4px; font: 600 10px -apple-system, sans-serif; color: #8d939b; letter-spacing: .06em; text-transform: uppercase; }
.tl-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(96px, 1fr)); gap: 6px; }
.tl-t { all: unset; box-sizing: border-box; position: relative; cursor: pointer; display: grid; gap: 2px; padding: 5px; border-radius: 7px; background: #171615; box-shadow: inset 0 0 0 1px #2a2927; font-size: 11px; color: #c4c8ce; }
.tl-t:hover { color: #fff; box-shadow: inset 0 0 0 1px #504e4b; }
.tl-t canvas { width: 100%; height: 28px; display: block; }
.tl-t span { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.tl-t.isA, .tl-t.isB { box-shadow: 0 0 0 1.5px #e455f0; color: #fff; }
.tl-t.isA::after, .tl-t.isB::after { position: absolute; top: 3px; right: 4px; font: 700 9px/1 -apple-system, sans-serif; color: #111; background: #e455f0; border-radius: 3px; padding: 2px 3px; }
.tl-t.isA::after { content: 'A'; } .tl-t.isB::after { content: 'B'; } .tl-t.isA.isB::after { content: 'A B'; }
@container dock (max-width: 900px) { .tonedrawer { grid-template-columns: 1fr; } }
/* the drawer's dials show their name and value (Morph and Amount both read as %) */
.tonedrawer .kn2 .kl, .tonedrawer .kn2:hover .kl { display: block; font-size: 11px; color: #c4c8ce; }
.tonedrawer .kn2 .kv, .tonedrawer .kn2:hover .kv { display: block; font-size: 10.5px; color: #8d939b; }
/* Tone previews: ▶ on every template (the chop through it), ♪ on a track's (the track itself), morph stops */
.tl-t .tl-sim { position: absolute; left: 6px; top: 4px; font: 600 9.5px -apple-system, sans-serif; font-style: normal; font-variant-numeric: tabular-nums; }
.tl-t .tl-play, .tl-t .tl-src { position: absolute; bottom: 4px; width: 20px; height: 20px; display: grid; place-items: center; border-radius: 50%; font: 9px/1 -apple-system, sans-serif; font-style: normal; color: #111; background: #c4c8ce; opacity: .55; }
.tl-t .tl-play { right: 4px; } .tl-t .tl-src { right: 28px; background: #8d939b; }
.tl-t:hover .tl-play, .tl-t:hover .tl-src { opacity: 1; } .tl-t .tl-play:hover, .tl-t .tl-src:hover { background: #fff; transform: scale(1.1); }
.tl-t span { padding-right: 22px; } .tl-t:has(.tl-src) span { padding-right: 46px; }
.td-morphs { gap: 4px; } .td-morphs button { min-width: 38px; padding: 4px 6px !important; font-variant-numeric: tabular-nums; }
.td-ml { font: 700 10.5px -apple-system, sans-serif; color: #8d939b; }
.td-morphs button[data-tn="sweep"] { margin-left: 8px; }

/* Pads & keys, sized (S was the original mini) and the piano */
.pfloat { --pd: 11px; --wk: 15px; --kh: 56px; }
.pfloat[data-size="s"] { --pd: 5px; --wk: 9px; --kh: 34px; }
.pfloat[data-size="l"] { --pd: 18px; --wk: 22px; --kh: 84px; }
.pf-grid { grid-template-columns: repeat(var(--cols), var(--pd)); grid-auto-rows: var(--pd); gap: calc(var(--pd) * .28 + 1px); }
.pfloat .pc-pad { width: var(--pd); height: var(--pd); border-radius: calc(var(--pd) * .25 + 1px); }
.pfloat[data-size="l"] .pf-name, .pfloat[data-size="l"] .pf-row button, .pfloat[data-size="l"] .pf-pick { font-size: 10.5px; max-width: none; }
.pf-keys { position: relative; width: calc(var(--whites) * var(--wk)); height: var(--kh); margin: 0 auto; }
.pf-keys.off { opacity: .4; }
.pk { position: absolute; top: 0; box-sizing: border-box; cursor: pointer; font-style: normal; }
.pk.white { left: calc(var(--x) * var(--wk)); width: calc(var(--wk) - 1px); height: 100%; border-radius: 0 0 3px 3px; background: linear-gradient(180deg, #d9dce0, #f4f5f6 70%, #c9ccd1); box-shadow: inset 0 -2px 0 rgba(0,0,0,.18); }
.pk.white.root { background: linear-gradient(180deg, color-mix(in srgb, var(--tc) 55%, #fff), #fff 75%); }
.pk.white b { position: absolute; bottom: 3px; left: 0; right: 0; text-align: center; font: 700 calc(var(--wk) * .42) -apple-system, sans-serif; color: #605e5a; }
.pfloat[data-size="s"] .pk.white b { display: none; }
.pk.black { left: calc(var(--x) * var(--wk) - var(--wk) * .32); width: calc(var(--wk) * .62); height: 60%; z-index: 2; border-radius: 0 0 2px 2px; background: linear-gradient(180deg, #1d1c1a, #363532); box-shadow: inset 0 -2px 0 rgba(255,255,255,.08), 0 1px 2px rgba(0,0,0,.5); }
.pk.hit { animation: none; }
.pk.white.hit { background: color-mix(in srgb, var(--tc) 70%, #fff); }
.pk.black.hit { background: var(--tc); }
.pf-oct { font: 600 9px -apple-system, sans-serif; color: #c4c8ce; min-width: 14px; text-align: center; align-self: center; font-variant-numeric: tabular-nums; }
.pfloat.keysview .pf-row { justify-content: flex-start; gap: 4px; } .pfloat.keysview .pc-rec { margin-left: auto; }

