.lv-hub .bigcap.chopping::after { display: block; -webkit-mask: url(img/caps/big-glow.png?v=mwpj9o89) center / 100% 100% no-repeat; mask: url(img/caps/big-glow.png?v=mwpj9o89) center / 100% 100% no-repeat; }
