:is(#dock, #arrhost) .bld .bl-from { color: #8a8a90; font-size: 12px; display: flex; gap: 6px; align-items: center; white-space: nowrap; min-width: 0; }
:is(#dock, #arrhost) .bld .bl-from select, :is(#dock, #arrhost) .bld select[data-into] { background: #131211; color: #fff; padding: 3px 8px; border-radius: 5px; box-shadow: inset 0 0 0 1px #2d2c2a; font-size: 11.5px; min-width: 0; max-width: 100%; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
:is(#dock, #arrhost) .bld .bl-moves { display: flex; justify-content: space-between; align-items: flex-end; gap: 10px; padding: 6px 12px 7px 10px; min-width: 0; }
