@media (prefers-reduced-motion: reduce) { :is(#dock, #arrhost) .bld .bl-sw i, :is(#dock, #arrhost) .bld .bl-sw i::after { transition: none; } }
:is(#dock, #arrhost) .bld .bl-main { display: flex; flex-direction: column; gap: 8px; padding: 9px 10px 10px; min-width: 0; min-height: 0; }
