#arrhost .bld.in-arr .bl-song-lanes .bl-tag { position: absolute; left: 4px; display: inline-flex; align-items: center; gap: 4px; height: 16px; padding: 0 5px 0 4px; border: 0; border-radius: 4px;
  background: rgba(6, 6, 6, .6); color: #9a9aa0; font: 600 9.5px/16px -apple-system, sans-serif; white-space: nowrap; cursor: pointer; }
#arrhost .bld.in-arr .bl-song-lanes span.bl-tag { cursor: default; }
