#arrhost .bld.in-arr .bl-song-lanes .bl-tag.on { color: #ffd9a0; }
#arrhost .bld.in-arr .bl-song-lanes .bl-rl { fill: #6d6a66; font: 600 9px -apple-system, sans-serif; }
#arrhost .bld.in-arr .bl-song-lanes .bl-rl.nw { fill: #ffd9a0; }
/* The song's own hits are solid, as in the arranger; only the new bars are outlines. */
#arrhost .bld svg .bl-old .bl-b { fill-opacity: 1; stroke-width: 0; opacity: .9; }
#arrhost .bld svg .bl-old .bl-w .bl-wc { opacity: 1; } #arrhost .bld svg .bl-old .bl-w .bl-wk { display: inline; }
#arrhost .bld svg .bl-old .bl-wb { opacity: .06; }
#arrhost .bld.in-arr .bl-song { display: flex; gap: 2px; height: 16px; flex: none; }
#arrhost .bld.in-arr .bl-song i { flex: 1 1 0; min-width: 0; border-radius: 3px; background: #191817; color: #6d6a66; font: 600 9px/16px -apple-system, sans-serif; font-style: normal; padding-left: 4px; overflow: hidden; white-space: nowrap; }
#arrhost .bld.in-arr .bl-song i.src { box-shadow: inset 0 0 0 1px rgba(255,181,71,.4); color: #b8a58a; }
#arrhost .bld.in-arr .bl-song i.nw { background: color-mix(in srgb, var(--amb) 30%, #191817); color: #ffd9a0; }

/* Hear it (tester, 2026-11-08: "you can hear it"): ▶ on every skill's picture and every pack's cover, ■ while it plays.
   A small round key over the art, always there (a name you can't hear shouldn't be on screen), brighter on hover and lit
   in the card's colour while it plays; a treatment's A/B key (Dry / With) shows beside it only while it plays. */
#splash.start .sk-row { position: relative; }
#splash.start .hear-key { all: unset; box-sizing: border-box; cursor: pointer; position: absolute; z-index: 2; display: grid; place-items: center; width: 26px; height: 26px; border-radius: 50%;
  color: #fff; background: rgba(9, 9, 8, .62); box-shadow: inset 0 0 0 1px rgba(255, 255, 255, .28), 0 1px 4px rgba(0, 0, 0, .5); backdrop-filter: blur(6px); -webkit-backdrop-filter: blur(6px);
  opacity: .82; transition: opacity 120ms, transform 120ms, background 120ms, box-shadow 120ms; }
#splash.start .hear-key svg { width: 13px; height: 13px; fill: currentColor; }
#splash.start .hear-key .hk-stop { display: none; }
#splash.start .hear-key.on .hk-play, #splash.start .hear-key.busy .hk-play { display: none; }
#splash.start .hear-key.on .hk-stop { display: block; }
#splash.start .hear-key:hover { opacity: 1; transform: scale(1.08); background: rgba(9, 9, 8, .8); }
#splash.start .hear-key:focus-visible { opacity: 1; box-shadow: inset 0 0 0 1.5px #fff; }
#splash.start .hear-key.on { opacity: 1; color: #0c0c0b; background: var(--g1, var(--pc, #fff)); box-shadow: 0 0 0 2px rgba(0, 0, 0, .35), 0 0 12px color-mix(in srgb, var(--g1, var(--pc, #fff)) 70%, transparent); }
#splash.start .hear-key.busy { opacity: 1; }
#splash.start .hear-key.busy::after { content: ''; width: 12px; height: 12px; border-radius: 50%; border: 2px solid rgba(255, 255, 255, .25); border-top-color: #fff; animation: hk-spin .7s linear infinite; }
@keyframes hk-spin { to { transform: rotate(360deg); } }
/* On a skill: the middle of its picture (the side list's 40 px thumbs: smaller). */
#splash.start .sk-thumb .hear-key { left: 50%; top: 50%; margin: -13px 0 0 -13px; }
#splash.start .sp-create:not(.pk-page) .sk-thumb .hear-key { width: 22px; height: 22px; margin: -11px 0 0 -11px; }
#splash.start .sp-create:not(.pk-page) .sk-thumb .hear-key svg { width: 11px; height: 11px; }
/* On a pack: the cover's lower right corner. */
#splash.start .pk .hear-key { right: 6px; bottom: 6px; width: 30px; height: 30px; }
#splash.start .pk .hear-key svg { width: 14px; height: 14px; }
/* A/B: which side plays, Dry or With (the skill), one click flips it in time. */
#splash.start .sk-ab { all: unset; box-sizing: border-box; cursor: pointer; position: absolute; z-index: 2; right: 8px; bottom: 7px; padding: 3px 8px; border-radius: 999px;
  font: 700 9px/1 -apple-system, sans-serif; letter-spacing: .08em; text-transform: uppercase; color: #0c0c0b; background: var(--g1); box-shadow: 0 0 10px color-mix(in srgb, var(--g1) 60%, transparent); }
#splash.start .sk-ab.dry { color: #e9ebee; background: rgba(255, 255, 255, .12); box-shadow: inset 0 0 0 1px rgba(255, 255, 255, .35); }
#splash.start .sk-ab[hidden] { display: none; }
@media (prefers-reduced-motion: reduce) { #splash.start .hear-key.busy::after { animation: none; } }
#splash.start .ph-art { position: relative; }
#splash.start .ph-art .hear-key { right: 6px; bottom: 6px; width: 30px; height: 30px; }
/* The tray: the picked skills as chips, ▶ Hear together, Add to song, in a row over the footer. */
#splash.start .sp-tray { display: flex; align-items: center; gap: 10px; min-width: 0; padding: 8px 2px; border-top: 1px solid rgba(255, 255, 255, .07); }
#splash.start .sp-tray[hidden] { display: none; }
#splash.start .sp-tray .sp-k { flex: none; display: grid; gap: 1px; }
#splash.start .sp-tray .tr-chips { flex: 1; min-width: 0; display: flex; gap: 6px; overflow-x: auto; scrollbar-width: none; }
#splash.start .tr-chip { flex: none; display: inline-flex; align-items: center; gap: 4px; padding: 3px 4px 3px 9px; border-radius: 999px; font: 500 11px -apple-system, sans-serif; color: #eef0f2;
  background: color-mix(in srgb, var(--g1) 16%, rgba(255, 255, 255, .04)); box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--g1) 55%, transparent); white-space: nowrap; }
#splash.start .tr-chip button { all: unset; cursor: pointer; display: grid; place-items: center; width: 16px; height: 16px; border-radius: 50%; font: 600 12px/1 -apple-system, sans-serif; color: #b5bac0; }
#splash.start .tr-chip button:hover { color: #fff; background: rgba(255, 255, 255, .12); }
#splash.start .sp-tray .capbtn { flex: none; }
#splash.start .tr-hear svg { width: 12px; height: 12px; fill: currentColor; margin-right: 5px; }
#splash.start .tr-hear .hk-stop, #splash.start .tr-hear.on .hk-play, #splash.start .tr-hear.busy .hk-play { display: none; }
#splash.start .tr-hear.on .hk-stop { display: inline; }
#splash.start .tr-hear.busy { opacity: .7; }

/* ==== The Bus (the bus fork; bus.ts): its row under the tracks, each track's send ring, and its window ==== */
.arr-name .arr-tn { flex: 1 1 auto; width: auto; min-width: 0; }
.arr-send { all: unset; cursor: ns-resize; flex: none; width: 18px; height: 18px; margin-left: 6px; border-radius: 50%; touch-action: none; opacity: .55; }
.arr-send.on, .arr-send:hover, .arr-row.sel .arr-send { opacity: 1; }
.arr-send svg { display: block; width: 18px; height: 18px; }
.arr-send:focus-visible { outline: 1px solid var(--tc); outline-offset: 1px; }
.arr-row.arr-bus { border-top: 1px solid #272624; }
.arr-bus .arr-tn { color: var(--tc); }
.arr-bn { font: 500 10px -apple-system, sans-serif; font-style: normal; color: #77746f; flex: none; }
.arr-buscv text { font: 600 10px -apple-system, sans-serif; }
/* The Bus open, in place (no window): each lane's clips stay under a send fader the width of the view, and the Bus row
   holds the chain, + Effect and the return. Both sit at the view's left edge however the arranger is scrolled. */
.arr-lane.arr-busov { display: grid; }
.arr-lane.arr-busov > * { grid-area: 1 / 1; }
.arr-lane.arr-busov > svg { opacity: .35; }
.bus-fader, .bus-bar { position: sticky; left: calc(var(--nw, 236px) + 2px); z-index: 1; align-self: stretch; justify-self: start; box-sizing: border-box; margin: 4px 0; }
/* A send as a slider (tester, 2026-11-10): its value first, in the track's colour (click: type one), then the rail. */
.bus-fader { display: flex; align-items: center; gap: 12px; padding: 0 12px 0 4px; border-radius: 6px; outline: none; background: rgba(16, 15, 14, .62); box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--tc) 22%, #292826); touch-action: none; }
.bus-fader:hover, .bus-fader:focus-visible { box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--tc) 55%, #292826); }
.bus-fader .bf-v { all: unset; flex: none; min-width: 112px; padding: 3px 8px; border-radius: 4px; cursor: text; font: 600 11px ui-monospace, Menlo, monospace; color: var(--tc); white-space: nowrap; display: flex; align-items: center; gap: 6px; }
.bus-fader .bf-v:hover { background: color-mix(in srgb, var(--tc) 12%, transparent); }
.bus-fader:not(.on) .bf-v { color: color-mix(in srgb, var(--tc) 55%, #726f6b); }
.bus-fader .bf-v .bf-vl { font: 600 9px -apple-system, sans-serif; letter-spacing: .08em; text-transform: uppercase; color: color-mix(in srgb, var(--tc) 70%, #9aa0a8); }
.bus-fader .bf-v input { all: unset; width: 44px; padding: 1px 4px; border-radius: 3px; background: #090908; box-shadow: inset 0 0 0 1px var(--tc); font: 600 11px ui-monospace, Menlo, monospace; color: var(--tc); }
.bus-fader .bf-rail { position: relative; flex: 1 1 auto; height: 4px; border-radius: 2px; background: #2d2c2a; cursor: pointer; }
.bus-fader .bf-rail::before { content: ''; position: absolute; inset: -9px 0; }
.bus-fader .bf-fill { position: absolute; left: 0; top: 0; bottom: 0; border-radius: 2px; background: var(--tc); box-shadow: 0 0 6px color-mix(in srgb, var(--tc) 50%, transparent); }
.bus-fader .bf-knob { position: absolute; top: 50%; width: 14px; height: 14px; margin: -7px 0 0 -7px; border-radius: 50%; background: radial-gradient(circle at 40% 32%, #f4f5f6, #cfd2d6 60%, #9da1a7); box-shadow: 0 1px 3px rgba(0, 0, 0, .6), 0 0 0 1px rgba(0, 0, 0, .35); }
.bus-fader:not(.on) .bf-fill { opacity: 0; }
.bus-fader:not(.on) .bf-knob { opacity: .55; }
.arr-busruler { display: flex; align-items: baseline; gap: 12px; height: 100%; padding: 0 12px; box-sizing: border-box; align-self: stretch; position: sticky; left: var(--nw, 236px); }
.arr-busruler b { font: 600 9.5px/30px -apple-system, sans-serif; letter-spacing: .12em; text-transform: uppercase; color: #ffb020; }
.arr-busruler span { font: 400 11px -apple-system, sans-serif; color: #7f7c77; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.arr-bus.open .arr-name { background: color-mix(in srgb, var(--tc) 9%, #121110); }
.bus-bar { display: flex; align-items: center; gap: 8px; min-width: 0; padding: 0 4px 0 10px; border-radius: 6px; font: 500 11px -apple-system, sans-serif; color: #d9dbde;
  background: color-mix(in srgb, var(--tc) 8%, #161514); box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--tc) 40%, #292826); }
.bus-bar .sp { flex: 1; }
.bus-bar .bb-q { white-space: nowrap; }
.bus-bar .bb-q b { color: var(--tc); }
.bus-bar small { color: #8a9099; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; min-width: 0; }
.bus-bar .bb-chain { display: flex; align-items: center; gap: 6px; min-width: 0; overflow: hidden; white-space: nowrap; }
.bus-bar .bb-fx { all: unset; box-sizing: border-box; cursor: pointer; font: inherit; color: inherit; padding: 2px 8px; border-radius: 5px; background: #121110; box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--tc) 35%, #282725); transition: background 140ms, box-shadow 140ms; }
.bus-bar .bb-fx:hover { background: color-mix(in srgb, var(--tc) 10%, #121110); }
.bus-bar .bb-fx:focus-visible { outline: 1px solid #8a8a90; outline-offset: 2px; }
.bus-bar .bb-fx.pick { color: #1a1408; background: var(--tc); box-shadow: 0 0 10px color-mix(in srgb, var(--tc) 45%, transparent); }
.bus-bar .bb-fx.off { opacity: .45; }
.bus-bar .bb-arr { font-style: normal; color: #615f5a; }
.bus-bar em { color: #726f6b; font-style: normal; }
/* (+ Effect fits inside the bar whatever its height, so it never crosses the bar's outline: tester, 2026-11-12.) */
.bus-bar .bb-btn { all: unset; flex: none; box-sizing: border-box; display: inline-flex; align-items: center; height: 22px; max-height: calc(100% - 6px); padding: 0 10px; border-radius: 5px; cursor: pointer; font: 600 10.5px -apple-system, sans-serif; color: #c4c8ce;
  background: linear-gradient(#2d2c2a, #252422); box-shadow: inset 0 1px 0 rgba(255, 255, 255, .06), 0 0 0 1px #131211; }
.bus-bar .bb-btn:hover { color: #fff; }
.bus-bar .bb-btn:focus-visible { outline: 1px solid var(--tc); outline-offset: 1px; }
.bus-bar .bb-btn.go { color: #1d1600; background: var(--tc); box-shadow: none; }
.bus-bar .bb-ret { display: flex; align-items: center; gap: 6px; flex: none; color: #8a9099; }
.bus-bar .bb-ret input { width: 110px; accent-color: var(--tc); }
.bus-bar .bb-ret b { width: 32px; text-align: right; font: 500 10.5px ui-monospace, Menlo, monospace; color: #c4c8ce; }
/* Build in the arranger: its takes as a row of the left column, the column's full width (tester, 2026-11-10). */
#arrhost .bld.in-arr .bl-takes { display: flex; align-items: center; gap: 6px; min-width: 0; }
#arrhost .bld.in-arr .bl-takes .bl-tk { font-size: 12px; color: var(--amb); margin-right: 2px; cursor: help; flex: none; }
#arrhost .bld.in-arr .bl-tks { display: grid; grid-template-columns: repeat(auto-fill, minmax(32px, 1fr)); gap: 5px; flex: 1 1 auto; min-width: 0; }
html body #arrhost .bld.in-arr .bl-takes .capbtn.bl-take { width: auto !important; height: 32px !important; font-size: 12px !important; }
html body #arrhost .bld.in-arr .bl-takes .capbtn.bl-take svg { width: 15px !important; height: 15px !important; }
/* The Bus open: the sends, their header and the Bus row lit as one block, and Done glowing on the Bus row (tester,
   2026-11-10: "the bus sends … should basically be highlighted from that bus section"). */
.arrange.bus-on .arr-in { box-shadow: inset 0 0 0 1.5px rgba(255, 176, 32, .55), inset 0 0 40px rgba(255, 176, 32, .05); border-radius: 8px; background: rgba(255, 176, 32, .025); }
.arrange.bus-on .arr-head, .arrange.bus-on .arr-head .arr-corner, .arrange.bus-on .arr-name { background: color-mix(in srgb, #ffb020 6%, #121110); }
.arrange.bus-on .arr-row:not(.arr-bus) .arr-tn { color: color-mix(in srgb, var(--tc) 85%, #fff); }
