#tour .tr-ask { position: fixed; display: flex; gap: 12px; pointer-events: auto; animation: tr-ask-in .24s ease-out both; }
@keyframes tr-ask-in { from { opacity: 0; transform: translateY(6px); } }
#tour .tr-ask button { all: unset; cursor: pointer; display: inline-flex; align-items: center; height: 40px; padding: 0 20px; border-radius: 9px; font: 600 14px -apple-system, system-ui, sans-serif; color: #d8dade;
  background: linear-gradient(#34312e, #262422); box-shadow: inset 0 1px 0 rgba(255, 255, 255, .08), 0 1px 0 #000, 0 3px 10px rgba(0, 0, 0, .55); }
