#sbwin .sb-q { all: unset; box-sizing: border-box; width: 300px; height: 32px; padding: 0 12px; border-radius: 8px; background: #1b1a18; box-shadow: inset 0 1px 3px #000a, inset 0 0 0 1px #33312e;
  font: 400 13px -apple-system, sans-serif; color: #eceae6; -webkit-user-select: text !important; user-select: text !important; }
