#sbwin .sb-s small { color: #8f8b85; font-size: 11px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
#sbwin .sb-cv { flex: none; width: 28px; height: 28px; border-radius: 5px; background-size: cover; background-position: center; display: grid; place-items: center; font-style: normal; }
