#sbwin .sb-fold::before { content: ''; width: 13px; height: 10px; border-radius: 2px; box-shadow: inset 0 0 0 1.5px #8f8b85; }
#sbwin .sb-add, #sbwin .sb-add small { color: #ffcf4d; }
