#tour .tr-pick .tp-item small { grid-column: -2; color: #8f8d88; font-size: 11px; }
#tour .tr-pick .tp-item:hover { background: #34322f; }
#tour .tr-pick .tp-item.on { background: #34322f; }
#tour .tr-pick .tp-item.on::after { content: ''; position: absolute; inset: 0; border-radius: 6px; box-shadow: inset 0 0 0 2px #ffcf4d; pointer-events: none; }
#tour .tr-pick .tp-keys { display: flex; gap: 8px; margin-top: 14px; }
#tour .tr-pick .tp-key { all: unset; cursor: pointer; height: 34px; padding: 0 16px; display: inline-flex; align-items: center; border-radius: 6px; background: #34322f; font-weight: 600; color: #ecebe8; }
#tour .tr-pick .tp-key:hover { background: #3d3b37; }
