.skin-lcd #dock .pv { background: #020202 !important; }
.skin-lcd .pv, .skin-lcd .pv .pv-head, .skin-lcd .pv .pv-lanes, .skin-lcd .pv .pvl, .skin-lcd .pv .pv-rackadd, .skin-lcd .pv .lv-tools { gap: var(--gap-lcd) !important; }
.skin-lcd .pv .pv-display, .skin-lcd .pv .pvl > .pvl-r, .skin-lcd .pv .pvl .pvl-view, .skin-lcd .pv .pv-rackadd .ra-r, .skin-lcd .pv .lv-tools > .lv-r { background: var(--cell-r) !important; }
/* The Track cell much dimmer (tester, 2026-10-25): a deep tint of the track's colour, "Track" in grey. */
.skin-lcd .pv .ftitle { background: var(--grain), linear-gradient(90deg, color-mix(in srgb, var(--tc, #22e6ff) 6%, #020303) 0%, color-mix(in srgb, var(--tc, #22e6ff) 9%, #040505) 100%) !important; }
