/* Slightly moulded keys (tester: "a little dry … maybe a slight skeuomorphism"). */
.skin-lcd .pv .pv-tcell .tbtns button { all: unset; box-sizing: border-box; cursor: pointer; height: 27px; padding: 0 6px; display: flex; align-items: center; justify-content: center; gap: 4px; border-radius: 6px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
  font: 500 11.5px -apple-system, sans-serif; color: #d2d4d8; text-shadow: 0 1px 0 rgba(0, 0, 0, .6);
  background: linear-gradient(180deg, #2e2d2b 0%, #252422 55%, #1f1e1c 100%);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, .09), inset 0 -1px 0 rgba(0, 0, 0, .4), 0 0 0 1px #0b0a09, 0 2px 3px rgba(0, 0, 0, .5);
  transition: filter 120ms, transform 80ms; }
