.skin-lcd .pv { position: relative; }
.skin-lcd .pv .rack-fly { z-index: 40; display: flex; align-items: stretch; gap: 4px; padding: 0; border-radius: 0; background: rgba(2, 2, 2, .96); box-shadow: none; overflow: visible; width: auto !important; max-height: none !important; }
.skin-lcd .pv .rack-fly .fo-cards { flex: 1; display: grid; grid-auto-flow: column; grid-auto-columns: minmax(0, 1fr); gap: 4px; min-width: 0; }
.skin-lcd .pv .rack-fly .fo-card { all: unset; box-sizing: border-box; position: relative; cursor: pointer; min-width: 0; display: flex; flex-direction: column; align-items: flex-start; gap: 5px; padding: 12px 12px 12px;
