.skin-lcd .pv .pv-lanes .pvl:not(.expanded):hover > .pvl-r, .skin-lcd .pv .pv-lanes .lv-autolane:hover > .lv-r { box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--tc, #22e6ff) 35%, transparent) !important; }
