.skin-lcd .pv .mods-grid .mg-btn { position: relative; min-height: 0; box-sizing: border-box; display: flex; flex-direction: column; align-items: flex-start; justify-content: space-between; padding: 6px 7px; border-radius: 6px; cursor: pointer; outline: none;
  background: linear-gradient(180deg, #1a1918, #121110); box-shadow: inset 0 1px 0 rgba(255, 255, 255, .05), 0 0 0 1px #050506, 0 2px 3px rgba(0, 0, 0, .45); transition: background 140ms, box-shadow 140ms, transform 80ms; }
.skin-lcd .pv .mods-grid .mg-n { font: 500 10.5px -apple-system, sans-serif; color: #8d9096; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; max-width: 100%; }
