.skin-lcd .pv .mods-grid .mg-btn:focus-visible { box-shadow: 0 0 0 1.5px var(--tc, #22e6ff); }
.skin-lcd .pv .mods-grid .mg-btn.has .mg-n { color: #c9ccd1; } .skin-lcd .pv .mods-grid .mg-btn.has .mg-ic { color: #8d9096; }
.skin-lcd .pv .mods-grid .mg-btn.on { background: radial-gradient(circle at 50% 60%, color-mix(in srgb, var(--tc, #22e6ff) 42%, #00262b), color-mix(in srgb, var(--tc, #22e6ff) 26%, #0e0e0d) 80%);
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--tc, #22e6ff) 45%, transparent), 0 0 12px color-mix(in srgb, var(--tc, #22e6ff) 18%, transparent), 0 0 0 1px #050506; }
.skin-lcd .pv .mods-grid .mg-btn.on .mg-n { color: #e8fcff; } .skin-lcd .pv .mods-grid .mg-btn.on .mg-ic { color: #e8fcff; filter: drop-shadow(0 0 4px var(--tc, #22e6ff)); }
.skin-lcd .pv .mods-grid .mg-btn.dis { opacity: .35; cursor: default; }
.skin-lcd .pv .mods-grid .mg-led { all: unset; position: absolute; top: 6px; right: 6px; width: 8px; height: 8px; border-radius: 50%; cursor: pointer; background: #2c2b29; box-shadow: inset 0 0 0 1px #3c3b38; }
.skin-lcd .pv .mods-grid .mg-led.on { background: var(--tc, #22e6ff); box-shadow: none; }
.skin-lcd .pv .mods-grid .mg-led:hover { transform: scale(1.25); }
