:is(body.keys-flat, body.keys-neon).skin-lcd .pv .sec-pow { border-image: none; background: #181716; box-shadow: inset 0 0 0 1px #3d3c39; }
:is(body.keys-flat, body.keys-neon).skin-lcd .pv .sec-pow.on { color: var(--tc, #22e6ff); box-shadow: inset 0 0 0 1.5px var(--tc, #22e6ff); }
