  --mk-on-light: url(img/modkeys/set1-on-light.png?v=mwpj9o89); --mk-press-light: url(img/modkeys/set1-press-light.png?v=mwpj9o89); }
body.skin-lcd.mk-1 #dock .pv .mods-grid .mg-n { color: rgba(236, 238, 241, .78) !important; text-shadow: 0 1px 1px rgba(0, 0, 0, .45) !important; font-weight: 550 !important; }
body.skin-lcd.mk-1 #dock .pv .mods-grid .mg-ic { color: #c3c6cb !important; filter: drop-shadow(0 1px 1px rgba(0, 0, 0, .4)) !important; }
body.skin-lcd.mk-1 #dock .pv .mods-grid .mg-btn:is(.on, :active:not(.dis)) .mg-n { color: #11110f !important; text-shadow: 0 .5px 0 rgba(255, 255, 255, .3) !important; font-weight: 550 !important; }
body.skin-lcd.mk-1 #dock .pv .mods-grid .mg-btn:is(.on, :active:not(.dis)) .mg-ic { color: #11110f !important; filter: none !important; }
/* Set 2, soft pads: a dark slate key; lit, a deeper glow, so the lit name and icon stay light. */
