}
body.theme-luna.skin-lcd {
  background: var(--l-bg) !important; color: var(--l-text);
  --t-hdr: var(--l-bar); --t-hdr-hi: var(--l-bar-hi); --t-ctl: var(--l-panel); --t-data: var(--l-lane);
  --cell-l: var(--l-panel); --cell-r: var(--l-lane); --grain: none; --grain-fine: none; --lcd-label: var(--l-dim);
}

/* ---- LUNA's keys, everywhere: header, panel, Mods, editors, S / M. ---- */
body.theme-luna.keys-flat.skin-lcd > header :is(.tkey, #home.brand, .hd-right #padsbtn),
