body.theme-luna.skin-lcd .pv :is(.hubkey, .key.hubkey, .pvl-addfx),
body.theme-luna :is(#grid, .pv) .sm-stack .cap {
  background: var(--l-key) !important; border: 0 solid transparent !important; border-image: url(img/luna/btn.png?v=mwpj9o89) 12 fill / 6px stretch !important;
  box-shadow: none !important; border-radius: 1px !important; color: var(--l-ink) !important; text-shadow: none !important; filter: none !important;
  font-family: var(--lf) !important; font-weight: 700 !important; text-transform: uppercase; }
