body.theme-luna.keys-flat.skin-lcd :is(.pv .pv-mini .pv-tog, .pv .pv-mini .tkey, .pv .pv-mini .pv-loop, .pv .pv-tcell .tbtns button, .pv .dirkeys button, .pv .mods-grid .mg-btn, :is(#dock :is(.pv-editor, .bld), #genpop, .rpop, #genwin, #sbwin, #packwin, .fxrack, .pwin, .rack-fly) .capbtn)::after { display: none !important; }
body.theme-luna.skin-lcd .pv :is(.hubkey, .key.hubkey) .ktint { display: none !important; }
/* Hover: a touch lighter. On: LUNA's orange key (S on: its yellow; M on: blue, white letter). */
body.theme-luna.keys-flat.skin-lcd > header :is(.tkey, #home.brand, .hd-right #padsbtn):hover,
body.theme-luna.keys-flat.skin-lcd :is(.pv .pv-mini .pv-tog, .pv .pv-mini .tkey, .pv .pv-mini .pv-loop, .pv .pv-tcell .tbtns button, .pv .dirkeys button, .pv .mods-grid .mg-btn, :is(#dock :is(.pv-editor, .bld), #genpop, .rpop, #genwin, #sbwin, #packwin, .fxrack, .pwin, .rack-fly) .capbtn):hover,
body.theme-luna.skin-lcd .pv :is(.hubkey, .key.hubkey, .pvl-addfx):hover, body.theme-luna :is(#grid, .pv) .sm-stack .cap:hover { filter: brightness(1.08) !important; box-shadow: none !important; }
body.theme-luna.keys-flat.skin-lcd > header .tkey.on:not(.t-play),
body.theme-luna.keys-flat.skin-lcd :is(.pv .pv-mini .pv-tog.on, .pv .pv-mini .tkey.on, .pv .pv-mini .pv-loop.on, .pv .pv-tcell .tbtns button.on, .pv .dirkeys button.on, .pv .mods-grid .mg-btn.on, :is(#dock :is(.pv-editor, .bld), #genpop, .rpop, #genwin, #sbwin, #packwin, .fxrack, .pwin, .rack-fly) .capbtn.on),
