body.theme-luna :is(#grid, .pv) .sm-stack .cap.mute:is(.on, [aria-pressed="true"]) { border-image: none !important; background: linear-gradient(180deg, #5cc6f5, #1e8fc4) !important; box-shadow: inset 0 0 0 1px var(--l-line) !important; color: #fff !important; }
body.theme-luna.keys-flat.skin-lcd .pv .mods-grid .mg-btn.dis { opacity: .45; }
/* Their icons and names, dark on the grey face. */
body.theme-luna.keys-flat.skin-lcd > header .tkey svg, body.theme-luna.keys-flat.skin-lcd > header #home .hd-start svg, body.theme-luna.keys-flat.skin-lcd > header .hd-right #padsbtn svg { fill: var(--l-ink) !important; stroke: var(--l-ink) !important; color: var(--l-ink) !important; filter: none !important; }
