body.theme-luna.skin-lcd .pv :is(.hubkey, .key.hubkey, .pv-mini, .pv-tcell, .dirkeys, .pv-editor .capbtn) svg, body.theme-luna.skin-lcd #dock .bld .capbtn svg { color: var(--l-ink) !important; stroke: var(--l-ink) !important; filter: none !important; }

/* ---- The header: LUNA's toolbar grey; readouts in its dark transport cells, grey capitals. ---- */
body.theme-luna.skin-lcd > header { background: var(--l-toolbar) !important; box-shadow: inset 0 -1px 0 var(--l-line) !important; border: 0 !important; }
body.theme-luna.skin-lcd > header :is(.hd-left, .hd-mid, .hd-strip, .hd-right) { background: none !important; box-shadow: none !important; }
