/* ---- The panel: LUNA's window and panels; section bars its mixer's (grey, white capitals); MODS its orange. ---- */
body.theme-luna.skin-lcd #dock .pv { background: var(--l-bg) !important; box-shadow: inset 0 0 0 1px var(--l-line) !important; }
body.theme-luna.skin-lcd .pv .ftitle { background: var(--l-header) !important; box-shadow: inset 4px 0 0 var(--tc, #22e6ff) !important; }
