body.theme-luna.skin-lcd .pv :is(.ftitle, .tinfo, .sinfo, .lane-tab, .mg-l, .ed-h, .pvl-r, .lv-r, .pv-tl) { font-family: var(--lf) !important; }
body.theme-luna.skin-lcd .pv :is(.tinfo, .sinfo) { color: var(--l-dim) !important; }
body.theme-luna.skin-lcd .pv .lane-tab, body.theme-luna.skin-lcd #dock .pv-editor .ed-h, body.theme-luna.skin-lcd .pv .pv-takes .pv-tl { color: #fff !important; text-transform: uppercase; font-weight: 700 !important; }
body.theme-luna.skin-lcd #dock .pv-editor .ed-h { background: var(--l-bar) !important; box-shadow: none !important; }
body.theme-luna.skin-lcd .pv .mods-grid { background: var(--l-mods) !important; border-radius: 3px; }
body.theme-luna.skin-lcd .pv .mods-grid .mg-l { color: #fff !important; text-transform: uppercase; font-weight: 700; }
body.theme-luna.skin-lcd .pv .sec-pow { box-shadow: none !important; text-shadow: none !important; filter: none !important; color: #5f6569 !important; }
body.theme-luna.skin-lcd .pv .sec-pow.on { color: var(--l-orange) !important; }
body.theme-luna.skin-lcd .pv .mg-led.on { background: var(--l-orange) !important; box-shadow: none !important; }

/* ---- Knobs: LUNA's black pan knob (its white line baked in), turned as Chop Shop turns its pointer; no arcs. ---- */
body.theme-luna .kdial svg, body.theme-luna .kdial .kbz, body.theme-luna .kdial .kbody { display: none !important; }
body.theme-luna .kdial > :is(.k3, .k3a) { display: none !important; }
body.theme-luna .kdial .kptr { display: block !important; content: url(img/luna/knob.png?v=mwpj9o89); filter: drop-shadow(0 1px 1px rgba(0, 0, 0, .6)) !important; }
body.theme-luna .kn2 .kl { color: var(--l-dim) !important; font-family: var(--lf) !important; font-weight: 700 !important; text-transform: uppercase; text-shadow: none !important; }
body.theme-luna .kn2 .kv { color: var(--l-text) !important; font-family: var(--lf) !important; text-shadow: none !important; }

/* ---- The grid: LUNA's timeline. Lit steps are clips, solid in the track's colour, the label black; unlit, an empty
   lane slot; the playhead a white edge; the selected one ringed in white. ---- */
body.theme-luna #grid, body.theme-luna #lower { background-color: var(--l-lane) !important; }
body.theme-luna.keys-flat #grid .key::before { background: #30363a !important; box-shadow: inset 0 0 0 1px #1c1f21 !important; border-radius: 3px !important; }
