body.theme-luna.keys-flat #grid .key.on .kl { color: #111 !important; }
body.theme-luna #grid .key { filter: none !important; }
/* Tracks: LUNA's track headers, the track's colour down the left edge, the name in white. */
body.theme-luna #grid .rowbtn { background: var(--l-header) !important; background-image: none !important; border-image: none !important; box-shadow: inset 4px 0 0 var(--tc, #888), inset 0 0 0 1px var(--l-line) !important; border-radius: 3px !important; filter: none !important; }
body.theme-luna #grid .row.rowsel .rowbtn, body.theme-luna #grid .row.lanesel .rowbtn { background: var(--l-header-sel) !important; }
body.theme-luna #grid .rowbtn :is(.nm, .nt) { color: #fff !important; font-family: var(--lf) !important; font-weight: 700 !important; text-shadow: none !important; }
body.theme-luna #grid .rowbtn .no { color: var(--tc) !important; }
