  background: radial-gradient(circle at 50% 45%, color-mix(in srgb, var(--tc, #22e6ff) 22%, transparent), transparent 70%), #0b0a0a;
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--tc, #22e6ff) 28%, transparent), 0 0 12px color-mix(in srgb, var(--tc, #22e6ff) 14%, transparent); }
