html body.lay-acc #dock .pv .acc-takes .at-screen::after { z-index: 3; }
html body.lay-acc.skin-lcd:not(.theme-luna) .hd-lcd :is(.hl-f b, .hl-bpm .bpmtext b) { color: #f2f2ee; text-shadow: 0 0 5px rgba(242, 242, 238, .45); }
