html body.theme-luna.lay-acc :is(#dock, #arrhost, header, #genpop, #luna-k) :is(.acc-key.on, .at-grid .key.on, .mods-grid .mg-btn.on, .capbtn.on, #luna-k) svg { color: var(--lk-on-ink) !important; stroke: currentColor; }
