html body.lay-acc:not(.theme-luna) #grid .row .rowbtn .rc button.cap.mute.on {
  border-image-source: url(img/caps/flat3d-dark-down.png?v=mwpj9o89) !important; color: #ff6b6f !important; text-shadow: 0 0 6px rgba(255, 80, 90, .55) !important; position: relative; }
html body.lay-acc #dock .pv :is(.acc-takes .at-keys > .pv-cmode, .acc-edcard .ec-tr .pv-mode) > button[data-tsm="mute"].on::before,
html body.lay-acc:not(.theme-luna) #grid .row .rowbtn .rc button.cap.mute.on::before {
