html body.lay-acc #arrhost .bld .bl-hear .bl-meter b:nth-child(4) { animation-delay: -.1s; animation-duration: .65s; }
@keyframes bl-meter { 0%, 100% { transform: scaleY(.25); } 50% { transform: scaleY(1); } }
@media (prefers-reduced-motion: reduce) { html body.lay-acc #arrhost .bld .bl-hear .bl-meter b { animation: none; transform: scaleY(.6); } }
/* The effect tiles in proportion with the dials under them (tester, 2026-11-15: "way too big for the tiles that are on the
   basic controls"): a size down, the FX Bus's and a track's Effects alike. */
html body.lay-acc .fxtab.fxcard { height: 30px !important; min-width: 100px !important; max-width: 180px !important; padding: 0 10px 0 8px !important; gap: 7px !important; border-radius: 6px !important; }
html body.lay-acc .fxtab.fxcard .fc-t { gap: 1px !important; }
html body.lay-acc .fxtab.fxcard .fc-t b { font-size: 10.5px !important; }
