html body.lay-acc #dock .pv > .acc-fxpanel .fxp-chainbar .fxtab.fxadd { height: 30px !important; padding: 0 11px !important; border-radius: 6px !important; font-size: 10.5px !important; }
html body.lay-acc .fxtab.fxadd { height: 30px !important; padding: 0 11px !important; border-radius: 6px !important; font-size: 10.5px !important; }

/* Trim one hit (main.ts openTrim): the rest dimmed, the hit over its lane, a yellow gripper at each end, Done below. */
.trim-shade { position: fixed; inset: 0; z-index: 900; background: rgba(10, 10, 9, .72); animation: trim-in .18s ease-out both; }
.trim-ed { position: fixed; z-index: 901; box-sizing: border-box; border-radius: 10px; background: #161514; font-family: -apple-system, system-ui, sans-serif;
  box-shadow: 0 0 0 1px color-mix(in srgb, var(--tc, #4fd18b) 45%, transparent), 0 12px 40px rgba(0, 0, 0, .6); animation: trim-in .18s ease-out both; }
@keyframes trim-in { from { opacity: 0; } }
.trim-ed .tr-head { position: absolute; left: 16px; top: 12px; right: 16px; font-size: 12.5px; color: #8b9097; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.trim-ed .tr-head b { color: #eef0f2; font-weight: 600; }
.trim-ed .tr-wave { position: absolute; left: 28px; right: 28px; top: 58px; bottom: 74px; }
