.trim-ed .tr-grip { position: absolute; top: -6px; bottom: -6px; width: 18px; margin-left: -9px; cursor: ew-resize; touch-action: none; outline: none; z-index: 1; }
.trim-ed .tr-grip::before { content: ''; position: absolute; left: 8px; top: 0; bottom: 0; width: 2px; background: #ffd36b; }
.trim-ed .tr-grip::after { content: ''; position: absolute; left: 2px; top: 50%; width: 14px; height: 34px; margin-top: -17px; border-radius: 5px; box-shadow: 0 2px 8px rgba(0, 0, 0, .6);
  background: repeating-linear-gradient(transparent 0 6px, rgba(0, 0, 0, .38) 6px 7px) center / 6px 21px no-repeat, #ffd36b; }
.trim-ed .tr-grip:focus-visible::after { box-shadow: 0 0 0 2px #fff, 0 2px 8px rgba(0, 0, 0, .6); }
