html body.lay-acc #arrhost .bld.in-arr .bl-s2 > .bl-opts { flex: 1 1 auto !important; min-height: 0 !important; overflow-y: auto; overflow-x: hidden; scrollbar-width: thin; }
html body.lay-acc #arrhost .bld.in-arr .bl-s2 > .bl-act { flex: none !important; margin-top: auto; }
@media (max-height: 820px) {
  html body.lay-acc #arrhost .bld.in-arr .bl-s2 { gap: 5px !important; padding-top: 8px !important; padding-bottom: 8px !important; }
  html body.lay-acc #arrhost .bld.in-arr .bl-s2 .bl-does span { -webkit-line-clamp: 1 !important; line-clamp: 1; }
  html body.lay-acc #arrhost .bld.in-arr .bl-s2 .bl-opts .bl-sw { height: 22px !important; }
  html body.lay-acc #arrhost .bld.in-arr .bl-s2 .bl-act .capbtn.wide.bl-hear { height: 28px !important; }
  html body.lay-acc #arrhost .bld.in-arr .bl-s2 .bl-opts .bl-gen .kn2 { --kw: 40px; --ks: 30px; }
}

/* ==== The Guide (help.ts, tester 2026-11-15: "a help menu … very impressive … a TOC with all the things that we could do
   in Chop Shop … With pointers … Screenshots"). A sheet over the app: contents left, the topic right, its screenshot with
   numbered rings on the controls it's about. The house greys; the pointers in the app's cyan. ==== */
#help { position: fixed; inset: 0; z-index: 9000; display: grid; place-items: center; padding: 18px; background: rgba(8, 8, 7, .62); backdrop-filter: blur(6px); -webkit-backdrop-filter: blur(6px);
  animation: hp-in 220ms ease both; }
@keyframes hp-in { from { opacity: 0; } }
#help .hp-box { position: relative; width: min(1380px, 100%); height: 100%; display: grid; grid-template-columns: 292px minmax(0, 1fr); overflow: hidden;
  background: #1b1a18; border-radius: 14px; box-shadow: 0 0 0 1px #34322f, 0 30px 80px rgba(0, 0, 0, .6); animation: hp-up 260ms cubic-bezier(.2, .8, .2, 1) both; }
@keyframes hp-up { from { transform: translateY(14px) scale(.985); } }
#help kbd { display: inline-block; min-width: 20px; padding: 1px 6px; border-radius: 5px; background: #2e2d2a; box-shadow: inset 0 -1px 0 #1a1918, 0 0 0 1px #45433f; font: 600 11px/18px -apple-system, sans-serif; color: #eceae6; text-align: center; vertical-align: 1px; }
#help a { color: inherit; text-decoration: none; }

/* The contents. */
#help .hp-nav { display: grid; grid-template-rows: auto auto minmax(0, 1fr); background: #161513; border-right: 1px solid #2c2b28; min-height: 0; }
#help .hp-brand { padding: 20px 20px 12px; font: 500 15px -apple-system, sans-serif; color: #a9a6a0; letter-spacing: .01em; }
#help .hp-brand b { color: #f2f0ec; font-weight: 700; }
#help .hp-search { display: flex; align-items: center; gap: 8px; margin: 0 14px 10px; padding: 0 10px; height: 34px; border-radius: 9px; background: #23221f; box-shadow: inset 0 0 0 1px #34322f; }
#help .hp-search:focus-within { box-shadow: inset 0 0 0 1px #22e6ff88; }
#help .hp-search svg { width: 15px; height: 15px; flex: none; fill: none; stroke: #8a8781; stroke-width: 1.6; stroke-linecap: round; }
#help .hp-search input { all: unset; flex: 1; min-width: 0; font: 13px -apple-system, sans-serif; color: #eceae6; }
#help .hp-search input::placeholder { color: #75726c; }
#help .hp-toc { overflow-y: auto; padding: 4px 10px 24px; scrollbar-width: thin; }
#help .hp-home, #help .hp-cht { display: flex; align-items: center; gap: 10px; padding: 8px 10px; border-radius: 8px; font: 600 13px -apple-system, sans-serif; color: #d9d6d0; }
#help .hp-cht i { font-style: normal; display: inline-grid; place-items: center; width: 20px; height: 20px; border-radius: 6px; background: #2a2926; color: #9f9c96; font: 700 11px -apple-system, sans-serif; flex: none; }
#help .hp-ch.open .hp-cht i { background: #22e6ff; color: #0d1416; }
#help .hp-home:hover, #help .hp-cht:hover, #help .hp-t:hover { background: #22211e; }
