#help .hp-kicker { margin: 0 0 6px; font: 700 11px -apple-system, sans-serif; letter-spacing: .09em; text-transform: uppercase; color: #22e6ff; }
#help h1 { margin: 0 0 10px; font: 700 30px/1.15 -apple-system, sans-serif; color: #f6f4f0; letter-spacing: -.01em; }
#help h2 { margin: 28px 0 10px; font: 700 13px -apple-system, sans-serif; letter-spacing: .06em; text-transform: uppercase; color: #8f8c86; }
#help .hp-lede { margin: 0 0 22px; font: 16px/1.5 -apple-system, sans-serif; color: #c4c1bb; max-width: 70ch; }
