/* The screenshot and its pointers: a ring round each control, its number on the ring's corner. */
#help .hp-fig { margin: 0 0 18px; }
#help .hp-shot { position: relative; margin: 0 auto; border-radius: 12px; overflow: hidden; background: #121110; box-shadow: 0 0 0 1px #34322f, 0 18px 44px rgba(0, 0, 0, .45); }
#help .hp-img { display: block; width: 100%; height: 100%; object-fit: cover; opacity: 0; transition: opacity 260ms ease; }
#help .hp-img.in { opacity: 1; }
#help .hp-ring { position: absolute; border-radius: 8px; box-shadow: 0 0 0 2px #22e6ff, 0 0 0 4px rgba(0, 0, 0, .55), 0 0 18px rgba(34, 230, 255, .45); pointer-events: auto; transition: box-shadow 160ms ease, background 160ms ease;
  animation: hp-ring 520ms cubic-bezier(.2, .8, .2, 1) both; }
#help .hp-ring:nth-child(3) { animation-delay: 80ms; } #help .hp-ring:nth-child(4) { animation-delay: 160ms; } #help .hp-ring:nth-child(5) { animation-delay: 240ms; }
#help .hp-ring:nth-child(6) { animation-delay: 320ms; } #help .hp-ring:nth-child(n+7) { animation-delay: 400ms; }
@keyframes hp-ring { from { opacity: 0; transform: scale(1.12); } }
#help .hp-ring b { position: absolute; left: -11px; top: -11px; display: grid; place-items: center; width: 22px; height: 22px; border-radius: 50%; background: #22e6ff; color: #071114;
  font: 800 12px -apple-system, sans-serif; box-shadow: 0 0 0 2px rgba(0, 0, 0, .6), 0 4px 10px rgba(0, 0, 0, .5); }
#help .hp-ring.hot { background: rgba(34, 230, 255, .14); box-shadow: 0 0 0 3px #22e6ff, 0 0 0 5px rgba(0, 0, 0, .55), 0 0 28px rgba(34, 230, 255, .75); z-index: 2; }
#help .hp-legend { list-style: none; margin: 0 0 6px; padding: 0; display: grid; grid-template-columns: repeat(auto-fill, minmax(330px, 1fr)); gap: 6px 18px; }
#help .hp-legend li { display: flex; gap: 10px; align-items: flex-start; padding: 7px 9px; border-radius: 9px; font: 13.5px/1.45 -apple-system, sans-serif; color: #c9c6c0; transition: background 160ms ease; }
#help .hp-legend li > b { flex: none; display: grid; place-items: center; width: 22px; height: 22px; border-radius: 50%; background: #22e6ff; color: #071114; font: 800 12px -apple-system, sans-serif; margin-top: 1px; }
#help .hp-legend li.hot { background: #22211d; }
#help .hp-steps { margin: 0; padding: 0; list-style: none; counter-reset: st; display: grid; gap: 8px; }
#help .hp-steps li { counter-increment: st; display: flex; gap: 12px; font: 14px/1.55 -apple-system, sans-serif; color: #cfccc6; }
#help .hp-steps li::before { content: counter(st); flex: none; display: grid; place-items: center; width: 24px; height: 24px; border-radius: 7px; background: #2a2926; color: #e4e1db; font: 700 12px -apple-system, sans-serif; }
#help .hp-tips { margin: 0; padding: 0 0 0 18px; display: grid; gap: 6px; }
#help .hp-tips li { font: 14px/1.55 -apple-system, sans-serif; color: #c9c6c0; }
#help .hp-tips li::marker { color: #22e6ff; }
#help .hp-keys { border-collapse: collapse; width: 100%; max-width: 640px; }
#help .hp-keys td { padding: 7px 10px 7px 0; border-bottom: 1px solid #2a2926; font: 13.5px/1.4 -apple-system, sans-serif; color: #c9c6c0; vertical-align: top; }
#help .hp-keys td:first-child { white-space: nowrap; width: 1%; padding-right: 18px; }

#help .hp-shot { cursor: zoom-in; }
/* A picture full size: over the Guide, as big as the window allows, its rings with it. */
#help.big .hp-fig { position: fixed; inset: 0; z-index: 20; margin: 0; display: grid; place-items: center; background: rgba(6, 6, 5, .86); cursor: zoom-out; animation: hp-in 180ms ease both; }
#help.big .hp-shot { width: min(96vw, calc(92vh * var(--ar))); max-width: none !important; cursor: zoom-out; }
#help.big .hp-ring b { transform: scale(1.15); }

/* Glitchy's line: him, then a speech bubble (no stripe down its side). */
#help .hp-glitchy { display: flex; align-items: flex-end; gap: 12px; margin: 28px 0 0; }
#help .hp-glitchy img { width: 58px; height: 58px; object-fit: contain; flex: none; filter: drop-shadow(0 6px 10px rgba(0, 0, 0, .5)); }
#help .hp-glitchy p { position: relative; margin: 0; padding: 11px 15px; border-radius: 14px 14px 14px 4px; background: #262521; box-shadow: inset 0 0 0 1px #393733; font: 14px/1.5 -apple-system, sans-serif; color: #dedbd5; max-width: 62ch; }
#help .hp-glitchy p b { display: block; font: 700 11px -apple-system, sans-serif; letter-spacing: .08em; text-transform: uppercase; color: #ffb347; margin-bottom: 2px; }

#help .hp-acts { display: flex; flex-wrap: wrap; align-items: center; gap: 12px 18px; margin: 28px 0 0; }
#help .hp-show { all: unset; cursor: pointer; display: inline-flex; align-items: center; gap: 8px; padding: 9px 16px 9px 12px; border-radius: 10px; background: #22e6ff; color: #071114; font: 700 13px -apple-system, sans-serif; box-shadow: 0 8px 22px rgba(34, 230, 255, .25); }
#help .hp-show:hover { background: #63eeff; }
#help .hp-show svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 1.8; }
#help .hp-see { font: 13px -apple-system, sans-serif; color: #8f8c86; }
#help .hp-pn { display: grid; grid-template-columns: 1fr 1fr; gap: 14px; margin-top: 40px; padding-top: 22px; border-top: 1px solid #2c2b28; }
#help .hp-pn a { display: grid; gap: 2px; padding: 12px 14px; border-radius: 10px; background: #201f1c; box-shadow: inset 0 0 0 1px #2e2d29; font: 600 14px -apple-system, sans-serif; color: #e8e5df; }
#help .hp-pn a:hover { box-shadow: inset 0 0 0 1px #4a4843; }
#help .hp-pn small { font: 600 11px -apple-system, sans-serif; letter-spacing: .06em; text-transform: uppercase; color: #7f7c76; }
#help .hp-next { text-align: right; }

/* The front page: a card a chapter. */
#help .hp-cards { display: grid; grid-template-columns: repeat(auto-fill, minmax(250px, 1fr)); gap: 14px; margin-top: 8px; }
#help .hp-card { display: grid; grid-template-rows: auto auto 1fr auto; border-radius: 12px; overflow: hidden; background: #201f1c; box-shadow: inset 0 0 0 1px #2f2e2a; transition: transform 160ms ease, box-shadow 160ms ease; }
#help .hp-card:hover { transform: translateY(-2px); box-shadow: inset 0 0 0 1px #4d4b45, 0 12px 28px rgba(0, 0, 0, .4); }
#help .hp-thumb { display: block; aspect-ratio: 16 / 9; background: #141312; overflow: hidden; }
#help .hp-thumb img { object-position: left top; }
#help .hp-cardt { display: flex; align-items: center; gap: 9px; padding: 12px 14px 4px; font: 700 15px -apple-system, sans-serif; color: #f2f0ec; }
#help .hp-cardt i { font-style: normal; display: inline-grid; place-items: center; width: 20px; height: 20px; border-radius: 6px; background: #22e6ff; color: #071114; font: 800 11px -apple-system, sans-serif; }
#help .hp-cardb { padding: 0 14px; font: 13px/1.45 -apple-system, sans-serif; color: #a8a59f; }
#help .hp-cardn { padding: 10px 14px 13px; font: 600 11px -apple-system, sans-serif; color: #75726c; letter-spacing: .04em; text-transform: uppercase; }

#help .hp-x { all: unset; cursor: pointer; position: absolute; top: 14px; right: 14px; z-index: 3; display: grid; place-items: center; width: 34px; height: 34px; border-radius: 9px; background: #262521; box-shadow: inset 0 0 0 1px #3a3833; }
#help .hp-x:hover { background: #312f2b; }
#help .hp-x svg { width: 14px; height: 14px; fill: none; stroke: #d8d5cf; stroke-width: 1.8; stroke-linecap: round; }

/* Show me: a ring on the real control, pulsing a few times. */
.hp-flash { position: fixed; z-index: 8999; pointer-events: none; border-radius: 10px; box-shadow: 0 0 0 3px #22e6ff, 0 0 0 6px rgba(0, 0, 0, .55), 0 0 30px rgba(34, 230, 255, .8); animation: hp-flash 800ms ease-in-out 3; }
@keyframes hp-flash { 50% { box-shadow: 0 0 0 5px #22e6ff, 0 0 0 9px rgba(0, 0, 0, .4), 0 0 46px rgba(34, 230, 255, 1); } }
.hp-toast { position: fixed; z-index: 9001; left: 50%; bottom: 28px; transform: translateX(-50%); padding: 10px 16px; border-radius: 10px; background: #262521; box-shadow: inset 0 0 0 1px #3d3b37, 0 12px 30px rgba(0, 0, 0, .5); font: 13px -apple-system, sans-serif; color: #e8e5df; animation: hp-in 200ms ease both; }

/* Where to open it: the start screen's pill beside Take the tour, and the ⋯ menu's first line. */
#splash.start > .sp-help { transform: translate(calc(-50% + 168px), -50%); }
#splash.start > .sp-retour.away + .sp-help { transform: translate(-50%, -50%); }
#hdmore-pop .hp-open { display: flex; align-items: center; gap: 8px; width: 100%; }
#hdmore-pop .hp-open kbd { margin-left: auto; padding: 0 5px; border-radius: 4px; background: #2e2d2a; box-shadow: 0 0 0 1px #45433f; font: 600 11px/16px -apple-system, sans-serif; }
@media (prefers-reduced-motion: reduce) { #help, #help .hp-box, #help .hp-ring, .hp-flash { animation: none; } #help .hp-main { scroll-behavior: auto; } }
